event.script:
 if (!Common.isFormSigned()) {
	if ((Common.isCBOn(Part1.FilingInfoSub.Amended))  ) {
		if  (!Common.hasValue(Part1.FilingInfoSub.BSAId)) {
			xfa.host.messageBox("If this report is amended and Prior Report BSA Identifier is known, Please enter the Prior Report BSA Identifier before you submit the form." );
		}
	}
}

FFBARFormActions.processSignButtonClick(this, "Sign the Form", "Remove Signature");

if (xfa.event.modifier && xfa.event.shift) {
	//Control + Save = export
	try {
		var ans = xfa.host.messageBox("Warning: You are about to export the form data as XML. " + 
			"This is meant for debugging/troubleshooting only, and is *not* a " + 
			"replacement for saving the form as PDF. You must still save this form normally " + 
			"(by clicking the Save button without the ctrl + shift keys), " + 
			"or your changes will be lost. Are you sure you want to continue?", "Warning: Export only", 1, 2);
		if (ans == 4) {
			xfa.host.exportData("", false);
		}
	} catch (e) {
	}
} else {
	try {
	xfa.host.messageBox("Please save your filing with a file name and location that you can easily access. " +
	"The file name and location must be accessed in order to submit your filing. An example of a filename is SMITHFBAR2013.PDF."); 
	 app.execMenuItem("SaveAs");
	} catch (e) {
	}
}

validate.script:
var valid = true;
if (Common.SIGNING != true && Common.VALIDATING == true && this.rawValue != 1) {
	//Form needs to be signed in order to be valid
	Common.ERRORS.push("This form needs to be signed in order to submit.");
  	valid;
} else {
	//This is hidden, so only return error if the user explicitly validates or attempts a submit
	valid;
}

event.script:
if (SignDateTime.rawValue != null && SignDateTime.rawValue != "" 
    && VerifyPINValue.rawValue != null && VerifyPINValue.rawValue != "") {
	var hash = Security.hex_sha1(VerifyPINValue.rawValue);

	if (hash == PINHash.rawValue) {
		xfa.host.messageBox("PIN is same.");
	} else {
		xfa.host.messageBox("PIN is NOT same.");
	}
}

if (!Common.isFormSigned()) {
	if (this.rawValue == "Z") {
	BSAForm.Header.Narrative.presence = "visible";
	BSAForm.Header.Narrative.ExplanationOrDescription.validate.nullTest = "error";
	Common.processFieldMakeRequired(BSAForm.Header.Narrative.ExplanationOrDescription);

	} else {
	    BSAForm.Header.Narrative.ExplanationOrDescription.rawValue = "";
	    Common.processFieldMakeNotRequired(BSAForm.Header.Narrative.ExplanationOrDescription);
	    BSAForm.Header.Narrative.ExplanationOrDescription.validate.nullTest = "disabled";
		BSAForm.Header.Narrative.presence = "invisible";
	}
	Common.processFieldRequiredHighlighting(BSAForm.Header.Narrative.ExplanationOrDescription);

	if (this.access == "open") {
		this.para.hAlign = "center";
	}
}
Common.processFieldExit(this);

