event.script:
if (!Common.isFormSigned()) {
	if (Common.isCBOn(this)){
			BSAId.access = "open";
			Common.processFieldExit(BSAId);

	} else {
		BSAId.validate.nullTest = "disabled";
		BSACommon.disableAndResetFields(BSAId); 
	}
}

