variables.script:
//Global variables
var initialFormValues;
var savedAfterSigned = false;
var VALIDATING = false;
var SIGNING = false;
var ERRORS = new Array();
var WARNINGS = new Array();
var REQUIRES_PIN = true;
var CLOSE_FORM_URL = "/CloseForm";

//Reader version checks
var MIN_READER_VERS = 8.103;
var MIN_READER_VERS_FORMATTED = "8.1.3";
var READER_DOWNLOAD_ADDRESS = "http://get.adobe.com/reader/otherversions/";

//Attachment file information:

//Maximum allowed file size of all attachments
var MAX_ATTACHMENTS_SIZE_BYTES = 62914560; //60MB in bytes
var MAX_ATTACHMENTS_SIZE_TEXT = "60MB (megabytes)"; //Text for error messages

//These are restricted by Adobe and can never be opened/saved by Reader
var BASE_INVALID_FILENAME = "\\.zip$|\\.exe$|\\.jar$|\\.bat$|\\.cmd$|\\.bas$|\\.sh$|\\.com$|\\.reg$|\\.vb$";
var BASE_INVALID_FILE_MIME_TYPE = "zip|msdownload|x-msdos-program|java-archive";

//These are addtional common filetypes not allowed for batch submissions
var BATCH_INVALID_FILENAME = "\\.pdf$|\\.xfd$|\\.doc$|\\.xls$|\\.ppt$|\\.xml$";
var BATCH_INVALID_FILE_MIME_TYPE = "pdf|xfd|msword|ms-excel|ms-powerpoint|image|video|xml";

var DONT_USE_ADOBE_ATT = "\n\nDo not use the built-in Adobe Reader attachments functionality to add or delete files on this form. " + 
				 		 "Use the \"Add Attachment\" and \"Delete Attachment\" buttons on this form instead." ;
var ALLOWED_NUM_ATTACHMENTS = 0;
var VALIDATE_ATTACHMENT_FILETYPE = "base";

//Regular Expressions to use
var AMT_REGEX 			= "^\\d{1,10}$";
var AMT_12_REGEX 		= "^\\d{1,12}$";
var AMT_15_REGEX 		= "^\\d{1,15}$";
var AMT_15_REGEX_XX 	= "^XX$|^\\d{1,15}$";
var AMT_REGEX_XX_NONE 	= "^XX$|^NONE$|^\\d{1,10}$";

var SSN_REGEX 			= "^\\d{9}$";
var SSN_REGEX_XX 		= "^\\d{9}$|^XX$";
var SSN_EIN_REGEX_NONE 	= "^\\d{9}$|^NONE$"; 
var SSN_REGEX_INVALID	= "^0{9}$|^1{9}$|^2{9}$|^3{9}$|^4{9}$|^5{9}$|^6{9}$|^7{9}$|^8{9}$|^9{9}$|^123456789$";

var DCN_REGEX	        = "^\\d{14}$";
var APOS_REGEX			= "\'"; 
var SLASH_REGEX			= "\/"; 

var ZIP_REGEX 			= "^\\d{5}$|^\\d{9}$";
var ZIP_REGEX_XX 		= "^\\d{5}$|^\\d{9}$|^XX$";
var ZIP_REGEX_INVALID   = "^0{5,9}$|^9{5,9}$|^\\d{5}0000$|^\\d{5}9999$";
var FOREIGN_POSTAL_CODE = "^[A-Z0-9]{1,9}$";

var TXT_INVALID_REGEX 	= /^(\s)*XX(\s)*$/i;

var FULL_PH_REGEX		= "^\\d{10}$";
var FULL_PH_REGEX_XX	= "^\\d{10}$|^XX$";
var AREA_CD_REGEX 		= "^\\d{3}$";
var AREA_CD_REGEX_XX	= "^\\d{3}$|^XX$";
var PH_REGEX 			= "^\\d{7}$";
var PH_REGEX_XX 		= "^\\d{7}$|^XX$";
var PH_REGEX_INVALID	= "^0{10}$|^9{10}$";

//Note: the raw value for a date field is formatted as yyyy-mm-dd - CANNOT BE USED WITH SPECIAL RESPONSE DATES
var UNKNOWN_DATE_REGEX  = "^XX$";
var DATE_REGEX	        = "^(19|20)[0-9][0-9]-(0[1-9]|1[0-2])-(0[1-9]|1[0-9]|2[0-9]|3[01])$";
var DATE_REGEX_XX       = "^(19|20)[0-9][0-9]-(0[1-9]|1[0-2])-(0[1-9]|1[0-9]|2[0-9]|3[01])$|" + UNKNOWN_DATE_REGEX;

//Note: date formats for special response dates have to validate the formatted value since the date could be invalid
var FORMATTED_DATE_REGEX = "^(0[1-9]|1[0-2])/(0[1-9]|1[0-9]|2[0-9]|3[01])/(19|20)[0-9][0-9]$";
var FORMATTED_DATE_WITH_ZEROS_REGEX = "^(0[0-9]|1[0-2])/(0[0-9]|1[0-9]|2[0-9]|3[01])/(19|20)[0-9][0-9]$";

//ASCII Allowed Characters
var INVALID_CHARS_REGEX = "[^\x20-\x7E\n\r\t]";


//These are common special characters and their replacements
var	SPECIAL_CHAR_REGEX = "\xa0|\xa9|\xae|\xb7|\u2018|\u2019|\u201c|\u201d|\u2026|\u2002|\u2003|\u2009|\u2013|\u2014|\u2122";
var	SPECIAL_CHAR_REPLACEMENTS = {
	    "\xa0": " ",
    	"\xa9": "(c)",
	    "\xae": "(r)",
	    "\xb7": "*",
	    "\u2018": "'",
    	"\u2019": "'",
	    "\u201c": '"',
    	"\u201d": '"',
	    "\u2026": "...",
    	"\u2002": " ",
	    "\u2003": " ",
    	"\u2009": " ",
	    "\u2013": "-",
    	"\u2014": "--",
	    "\u2122": "(tm)"
	};

//Constants
var BUTTON_FILL_COLOR = "212,208,200" ;
var BUTTON_FONT_COLOR = "0,0,0";
var BUTTON_DISABLED_FONT_COLOR = "192,192,192";

var BUTTON_DISABLED_FILL_COLOR = "128,128,128" ;
var NORMAL_FIELD_COLOR = "255,255,255";
var DISABLED_FIELD_COLOR = "215,215,215";

//DO NOT USE THE COLORS THAT END WITH _STATE_XX
//THESE ARE FOR INTERNAL USE ONLY TO KEEP STATE BETWEEN SAVES
var BUTTON_DISABLED_FILL_COLOR_STATE_RO = "128,128,127" ;
var BUTTON_DISABLED_FILL_COLOR_STATE_PRO = "128,127,128" ;
var BUTTON_DISABLED_FILL_COLOR_STATE_NONINT = "127,128,128" ;

var NORMAL_FIELD_COLOR_STATE_RO  = "255,255,254";
var NORMAL_FIELD_COLOR_STATE_PRO = "255,254,255";
var NORMAL_FIELD_COLOR_STATE_NONINT = "254,255,255";

var DISABLED_FIELD_COLOR_STATE_RO  = "215,215,214";
var DISABLED_FIELD_COLOR_STATE_PRO = "215,214,215";
var DISABLED_FIELD_COLOR_STATE_NONINT = "214,215,215";
//END DO NOT USE

var REQUIRED_FIELD_COLOR = "255,255,170";
var RECOMMENDED_FIELD_COLOR = "200,255,255";
var INVALID_FIELD_COLOR = "240, 0, 0";

var ALL_DISABLED = false;

var SIGNED_MSG = "This form has been signed and cannot be altered.";

function getSubmitButton() {
	if (COMMON_SubmitButton != null) {
		return xfa.form.resolveNode(COMMON_SubmitButton.value);
	} else {
		return null;
	}
}

function getSubmittedFlagField() {
	var submitButton = getSubmitButton();
	if (submitButton != null) {
		return submitButton.parent.resolveNode("Submitted");
	} else {
		return null;
	}
}

function getValidateButton() {
	if (COMMON_ValidateButton != null) {
		return xfa.form.resolveNode(COMMON_ValidateButton.value);
	} else {
		return null;
	}
}

//Not all forms have/need action fields; in this case the value will be set to "false"
function getActionFields() {
	if (COMMON_ActionFields != null && COMMON_ActionFields.value != "false") {
		return xfa.form.resolveNode(COMMON_ActionFields.value);
	} else {
		return null;
	}
}

function setNoPINRequired() {
	REQUIRES_PIN = false;
}

function setPINRequired() {
	REQUIRES_PIN = true;
}

function getRequiresPIN() {
	return REQUIRES_PIN;
}

function getFormSubmissionURLField() {
	if (COMMON_SubmitURLField != null) {
		return xfa.form.resolveNode(COMMON_SubmitURLField.value);
	} else {
		return null;
	}
}

function getFormInstructionPath() {
	var submissionurl = getFormSubmissionURL();
	var urlTokens = new Array();
	if ( submissionurl != null ) {
		urlTokens = submissionurl.split("/");

	}	
	var instructionPath=""; 
	for ( var i = 0; i < urlTokens.length - 1 ; i++ ) {
		if ( urlTokens[i] != null ) {
			instructionPath += urlTokens[i] + "/";
		}
	}
	return instructionPath + "docs/";	 
}

function getNumFormsReported() {
	var numForms = null;
	try {
		if (COMMON_NumFormsReported != null) {
  			numForms = xfa.form.resolveNode(COMMON_NumFormsReported.value).rawValue;
		} 
	}
	catch(e) {
	}
	return numForms;
}

function getFormSubmissionURL() {
	var submitURLFld = getFormSubmissionURLField();
	if (submitURLFld != null) { 
		return submitURLFld.rawValue;
	} else {
		return null;
	}
}

function getFormSubmissionType() {
	if (COMMON_FilingTypeField != null) {
		return xfa.form.resolveNode(COMMON_FilingTypeField.value).rawValue;
	} else {
		return null;
	}
}

function getFormSubmissionName() {
	if (COMMON_FilingNameField != null) {
		return xfa.form.resolveNode(COMMON_FilingNameField.value).rawValue;
	} else {
		return null;
	}
}

function getFormRoot() {
	return xfa.form.resolveNode("#subform[0]");
}

function hasValue(node) {
	return (node.rawValue != null && node.rawValue != "");
}

function hasNoValue(node) { 
	return (!hasValue(node));
}

function trim(str) {
    return ((str == null) ? null : str.replace(/^\s+|\s+$/g, ''));
}

function isFormSigned() {
	return (Common.getRequiresPIN() && Common.isCBOn(getActionFields().Signed));
}

function enableDisableSubmitButton(oNode) {
	if((!Common.getRequiresPIN() || Common.isCBOn(getActionFields().Signed)) && Common.savedAfterSigned) {
		oNode.access = "open";
	    Common.setFillColor(oNode, Common.BUTTON_FILL_COLOR);
		Common.setFontColor(oNode, Common.BUTTON_FONT_COLOR);
	} else {
		oNode.access = "readOnly";
		Common.setFillColor(oNode, Common.BUTTON_DISABLED_FILL_COLOR);
		Common.setFontColor(oNode, Common.BUTTON_DISABLED_FONT_COLOR);
	}
}

function setFieldAlwaysEnabled(oNode) {
	addExtrasNode(oNode, "boolean", "alwaysEnabled", true);
}

function unsetFieldAlwaysEnabled(oNode) {
	addExtrasNode(oNode, "boolean", "alwaysEnabled", false);
}

function isFieldAlwaysEnabled(oNode) {
	var enabledFlag = getExtrasNodeValue(oNode, "alwaysEnabled");
	return (enabledFlag != null && enabledFlag == true);
}

function disableAndResetFields(root) {
	Common.ProcessFields(root, "Common.__disableAndResetFieldNoUI");
}

//Only to be used when signing the form
function lockAllFields(root) {
	try {
		if (!ALL_DISABLED) {
			Common.ProcessFields(root, "Common.__showFieldLocked");
		}
	} catch (e) {
		//Error
	}
	ALL_DISABLED = true;
}

function enableFields(root) {
	Common.ProcessFields(root, "Common.__internalEnableField");
}

//Only to be used when signing the form
function unlockAllFields(root) {
	try {
		if (ALL_DISABLED) {
			Common.ProcessFields(root, "Common.__internalEnableField");
		}
	} catch (e) {
		//Error
	}
	ALL_DISABLED = false;
}

function __showFieldLocked(oNode) {
	__internalDisableField(oNode, true, false, true);
}

function __disableAndResetFieldNoUI(oNode) {
	__internalDisableField(oNode, false, true, false);
}

//Functions to handle the custom 'extras' nodes; use with caution
//NOTE: setting of the extras node DOES NOT save with the form,
//so this can only be used when the field can re-initialize itself
//without the need of the extras node.
function addExtrasNode(oNode, extrasType, extrasName, value) {
	//Only add it if it is not already there
	if (!extrasNodeExists(oNode, extrasName)) { 
		var node = xfa.form.createNode(extrasType, extrasName); 
    	node.value = value; 
		oNode.extras.nodes.append(node); 
	}
}

function extrasNodeExists(oNode, extrasName) {
	return oNode.extras.nodes.namedItem(extrasName) != null;
}

function removeExtrasNode(oNode, extrasName) {
	var node = oNode.extras.nodes.namedItem(extrasName);
	if (node != null) {
		oNode.extras.nodes.remove(node);
	}
}

function getExtrasNodeValue(oNode, extrasName) {
	var node = oNode.extras.nodes.namedItem(extrasName);
	if (node != null) {
		return node.value;
	} else {
		return null;
	}
}

function __internalDisableField(oNode, showFieldsAsDisabled, resetValue, saveState) {
	if (oNode != null) {
		if (saveState && oNode.access != "open" && !isFieldAlwaysEnabled(oNode)) {
			//Already not enabled, just save it's state
			if (resetValue && oNode.rawValue != null) {
				oNode.rawValue = null;
			}
			Common.disableField(oNode, true, showFieldsAsDisabled, true);
		} else {		
			if (!isFieldAlwaysEnabled(oNode)) {
				if (resetValue && oNode.rawValue != null) {
					oNode.rawValue = null;
				}
			    Common.disableField(oNode, false, showFieldsAsDisabled, false);
			}
		}
	}
}

//WARNING: this ALWAYS disables a field, regardless of the existing state and enabled state is NOT saved
function disableField(oNode, visualOnly, showFieldsAsDisabled, saveFieldState) {
	if (arguments.length < 4) {
		saveFieldState = false;
	}

	if (arguments.length < 3) {
		showFieldsAsDisabled = true;
	}

	if (arguments.length < 2) {
		visualOnly = false;
    }

	if (!visualOnly) {
		oNode.access = "readOnly";
	}

	if (oNode.ui.oneOfChild.className == "button") {
		if (saveFieldState) {
			if (oNode.access == "readOnly") {
				setFillColor(oNode, BUTTON_DISABLED_FILL_COLOR_STATE_RO);
			} else if (oNode.access == "protected") { 
				setFillColor(oNode, BUTTON_DISABLED_FILL_COLOR_STATE_PRO);
			} else if (oNode.access == "nonInteractive") { 
				setFillColor(oNode, BUTTON_DISABLED_FILL_COLOR_STATE_NONINT);
			} else {
				setFillColor(oNode, BUTTON_DISABLED_FILL_COLOR);
			}
		} else {
			setFillColor(oNode, BUTTON_DISABLED_FILL_COLOR);
		}
		setFontColor(oNode, BUTTON_DISABLED_FONT_COLOR);
	} else {
		if (saveFieldState) {
			if (oNode.access == "readOnly") {
				setFillColor(oNode, (showFieldsAsDisabled) ? DISABLED_FIELD_COLOR_STATE_RO : NORMAL_FIELD_COLOR_STATE_RO);
			} else if (oNode.access == "protected") { 
				setFillColor(oNode, (showFieldsAsDisabled) ? DISABLED_FIELD_COLOR_STATE_PRO : NORMAL_FIELD_COLOR_STATE_PRO);
			} else if (oNode.access == "nonInteractive") { 
				setFillColor(oNode, (showFieldsAsDisabled) ? DISABLED_FIELD_COLOR_STATE_NONINT : NORMAL_FIELD_COLOR_STATE_NONINT);
			} else {
				setFillColor(oNode, (showFieldsAsDisabled) ? DISABLED_FIELD_COLOR : NORMAL_FIELD_COLOR);
			}
		} else {
			setFillColor(oNode, (showFieldsAsDisabled) ? DISABLED_FIELD_COLOR : NORMAL_FIELD_COLOR);
		}
	}
	processFieldRequiredHighlighting(oNode);
}

function __internalEnableField(oNode) {
	if (oNode) {
		//Check to see if this should remain R/O, protected or non-interactive
		var fieldFillColor = getFillColor(oNode);

		if ((fieldFillColor != DISABLED_FIELD_COLOR_STATE_RO && fieldFillColor != NORMAL_FIELD_COLOR_STATE_RO) &&
			(fieldFillColor != DISABLED_FIELD_COLOR_STATE_PRO && fieldFillColor != NORMAL_FIELD_COLOR_STATE_PRO) &&
		    (fieldFillColor != DISABLED_FIELD_COLOR_STATE_NONINT && fieldFillColor != NORMAL_FIELD_COLOR_STATE_NONINT) &&
		    (!isFieldAlwaysEnabled(oNode))) {
			Common.enableField(oNode);
		} else {
			Common.enableField(oNode, true);
		}
	}
}

//WARNING: this ALWAYS enables a field, regardless of the existing state and enabled state is NOT saved
function enableField(oNode, visualOnly) {
	if (arguments.length < 2) {
	   visualOnly = false;
    }

	if (!visualOnly) {
		oNode.access = "open";
	}

	if (oNode.ui.oneOfChild.className == "button") {
		setFillColor(oNode, BUTTON_FILL_COLOR);
		setFontColor(oNode, BUTTON_FONT_COLOR);
	} else {
		setFillColor(oNode, NORMAL_FIELD_COLOR);
	}
	processFieldRequiredHighlighting(oNode);
}

function processFieldValidityUI(oNode, valid) {
	var className = oNode.ui.oneOfChild.className;
	var isButton = (oNode.ui.oneOfChild.className == "button");

	if (oNode && !isButton) {
 		if (valid == true) {
	        // Set as white
	      	processFieldRequiredHighlighting(oNode, true);
		} else {
            // Set as red for invalid
		    setFillColor(oNode, INVALID_FIELD_COLOR);
		}
	}
	return valid;
}

function validateFieldValue(oNode, validValues, invalidValues, noUI) {
	var returnValue = __validateFieldValue(oNode, validValues, invalidValues);
	return processFieldValidity(oNode, returnValue);
}

function __validateFieldValue(oNode, validValues, invalidValues) {
	var returnValue = false;
	var valueToTest = oNode.rawValue;

	if (valueToTest != null && valueToTest != "") {
		//Check for valid matches
		if (validValues != null) {
			for (var i=0;i<validValues.length;i++) {
				var regEx = new RegExp(validValues[i]);
				if (regEx.test(valueToTest)) {
			  		returnValue = true;
		  			break;
				}
			}
		} else {
			returnValue = true;
		}

		//Check for any invalid matches
		if (invalidValues != null) {
			for (var i=0;i<invalidValues.length;i++) {
				var regEx = new RegExp(invalidValues[i]);
				if (regEx.test(valueToTest)) {
			  		returnValue = false;
		  			break;
				}
			}
		}
	} else {
		returnValue = true;
	}
	return returnValue;
}

function processFieldValidity(oNode, isValid, noUI) {
	if ((noUI == null || noUI == false) && oNode.ui != null) {
		Common.processFieldValidityUI(oNode, isValid);
	}

	if (Common.VALIDATING == true && !isValid) {
	  	//add the message instead
	  	var errorMsgs = oNode.validate.message.resolveNodes("#text[*]");
	  	if (errorMsgs) {
	  		for (var i=0;i<errorMsgs.length;i++) {
	  			if (errorMsgs.item(i).getAttribute("name") == "scriptTest") {
			  		__setValidationErrorMessage(errorMsgs.item(i).value);
			  		break;
			  	}
			}
	  	}
	  	return true;
	} else {
		return isValid;
	}
}

function __setValidationErrorMessage(sErrorMessage) {
	//no dups
	var hasDup = false;
	for (var i=0;i<Common.ERRORS.length;i++) {
		if (Common.ERRORS[i] == sErrorMessage) {
			hasDup = true;
			break;
		}
	}

	if (!hasDup) {
		Common.ERRORS.push(sErrorMessage);
	}
}

function __setValidationWarningMessage(sWarningMessage) {
	//no dups
	var hasDup = false;
	for (var i=0;i<Common.WARNINGS.length;i++) {
		if (Common.WARNINGS[i] == sWarningMessage) {
			hasDup = true;
			break;
		}
	}

	if (!hasDup) {
		Common.WARNINGS.push(sWarningMessage);
	}
}

function checkReaderFieldHighlighting() {
	if (app.runtimeHighlight) {
		var answer = xfa.host.messageBox("BSA E-Filing forms require that you turn off the Adobe Reader \"Highlight Fields\" "
			+ "option in order to effectively use this form. The Adobe Reader \"Highlight Fields\" option has been turned off.", 
			"Turning off \"Highlight Fields\" option", 1, 0);
		app.runtimeHighlight = false;
	}
}

function isValidReaderVersion() {
	return (app.viewerVersion >= MIN_READER_VERS);
}

function checkViewerVersion() {
    var appVer = app.viewerVersion;   

    if (!isValidReaderVersion()) { 
        var viewerMsg = "You are currently using an unsupported version of Adobe Reader. "
	        + "This form requires Adobe Reader version " + MIN_READER_VERS_FORMATTED + " or newer. "
	        + "You will not be able to fill-in or submit this form unless you use a supported version of the Adobe Reader. \n\n"
			+ "Click 'OK' to download and install the latest version of Acrobat Reader from:\n" 
        	+ READER_DOWNLOAD_ADDRESS ;
        var ans = xfa.host.messageBox(viewerMsg, "Invalid Reader Version", 0, 1);
        if (ans == 1) {
			xfa.host.gotoURL(READER_DOWNLOAD_ADDRESS);
        }
        return false;
    }
    return true;
}

function test(oNode) {
	xfa.host.messageBox("Node name: " + oNode.name + ", Node UI class: " + oNode.ui.oneOfChild.className);
}

//if not required, or not recommended, forceNormalFill if set will
//always reset the field color to normal
function processFieldRequiredHighlighting(oNode, forceNormalFill) {
	var isButton = (oNode.ui.oneOfChild.className == "button");

	if (oNode.access == "open" && !isButton) {	
		if (IsRequired(oNode)) {
			setFillColor(oNode, REQUIRED_FIELD_COLOR);
			return true;
		} else if (IsRecommended(oNode)) {
			setFillColor(oNode, RECOMMENDED_FIELD_COLOR);
			return true;
		} else {
			//It is not required or recommended, but the value may
			//have been cleared after it was invalid, so we check here
			var currentFill = getFillColor(oNode);
			if (currentFill != INVALID_FIELD_COLOR || 
				(forceNormalFill!= null && forceNormalFill== true)) {
				setFillColor(oNode, NORMAL_FIELD_COLOR);
			} else if (currentFill == INVALID_FIELD_COLOR && hasNoValue(oNode)) {
				setFillColor(oNode, NORMAL_FIELD_COLOR);
			}
			return false;
		}
	} 
}

function getFillColor(oNode) {
	var uiClassName = oNode.ui.oneOfChild.className;
	var uiNode = oNode;

	//Buttons do not have UI borders
	if (uiClassName != "button") {
		uiNode = oNode.ui.oneOfChild;
	}

	if (uiNode.border) {
		return uiNode.border.fill.color.value;
	} else {
		return "";
	}
}

function setFillColor(oNode, sColor) {
	var uiClassName = oNode.ui.oneOfChild.className;
	var uiNode = oNode;

	//Buttons do not have UI borders
	if (uiClassName != "button") {
		uiNode = oNode.ui.oneOfChild;
	}

	if (uiNode.border) {
		uiNode.border.fill.color.value = sColor;
	}
}

function setFontColor(oNode, sColor) {
	if (oNode) {
		oNode.caption.font.fill.color.value = sColor;
	}
}

// Returns true if the field is mandatory and isn't filled.
function IsRequired(oField) {
	return IsRequiredOrRecommended(oField, "error");
}

// Returns true if the field is recommended and isn't filled.
function IsRecommended(oField) {
	return IsRequiredOrRecommended(oField, "warning");
}

// Returns true if the field is mandatory or recommended and isn't filled.
function IsRequiredOrRecommended(oField, testValue) {
	if (oField.validate.nullTest == testValue && (oField.rawValue == null || oField.rawValue.length == 0)) {
		return true; // mandatory field
	}

	// If the field's parent is an exclusion group, the exclusion group's mandatory setting applies to all fields it contains.
	if (oField.parent.className == "exclGroup" && oField.parent.validate.nullTest == testValue 
		&& (oField.parent.rawValue == null || oField.parent.rawValue.length == 0)) {
		return true; // parent is a mandatory exclusion group (e.g. radio button list)
	}

	if (oField.ui.oneOfChild.className == "checkButton" && oField.validate.nullTest == testValue) {
		// Check boxes always have a default value (so it won't be null neither will it be an empty string).
		//  If a check box is mandatory, we'll assume that means it's value should either be "on" or "neutral" but not "off".
		// (Note that while check boxes can't be made mandatory via Designer's UI, they can be via script: See the Initialize script of the
		//  CheckBox3 field.)
		// By definition (in the XFA 2.2 spec), the "off" value is the second value in the first <items> child node.
		var oItemsList = oField.resolveNodes("#items"); // note the "#" prefix to access the <items> child nodes explicitely
		if (oItemsList.length > 0) {
			var oValueList = oItemsList.item(0).nodes;
			if (oValueList.length > 1) {
				var sOffValue = oValueList.item(1).value;
				if (oField.rawValue == sOffValue) {
					return true; // found a mandatory check box whose value is still set to "off"
				}
			}
		}
	}
	return false;
}

function ProcessFields(oNode, functionName) {
	var nNumProcessed = 0;

	if (oNode.className == "exclGroup" || oNode.className == "subform"  ||
	    oNode.className == "subformSet" || oNode.className == "area") {
		// Look for child fields.
		for (var i = 0; i < oNode.nodes.length; i++) {
			var oChildNode = oNode.nodes.item(i);
			nNumProcessed += ProcessFields(oChildNode, functionName);
		}
	}
	else if (oNode.className == "field") {
		var className = oNode.ui.oneOfChild.className;

		switch (className) {
			case "button":
				if (eval(functionName + "(oNode)"))	{
					nNumProcessed++;
				}
				break;

			case "checkButton":
				if (oNode.parent.className == "exclGroup") {
					// checkButtons inside exclusion groups are radio buttons
					if (eval(functionName + "(oNode)"))	{
						nNumProcessed++;
					}
				} else {
					// otherwise, they're check boxes
					if (eval(functionName + "(oNode)")) {
						nNumProcessed++;
					}
				}
				break;

			case "choiceList":
			{
				var oUITypeNode = oNode.ui.resolveNode("#choiceList");

				if (oUITypeNode.open == "userControl") {
					// drop down list / combo box
					if (eval(functionName + "(oNode)")) {
						nNumProcessed++;
					}
				} else {
					// otherwise, it's a list box
					if (eval(functionName + "(oNode)"))	{
						nNumProcessed++;
					}
				}
				break;
			}

			case "dateTimeEdit":		
			case "imageEdit":
			case "numericEdit":
			case "passwordEdit":
			case "textEdit":
			case "signature":
			case "barcode":
				if (eval(functionName + "(oNode)")) {
					nNumProcessed++;
				}

			default:
				// unknown field type
				break;
		}
	}
	return nNumProcessed;
}

function processFormValidation() {
	var valid = false;

	try {
		Common.VALIDATING = true;
		valid = xfa.form.execValidate();
		Common.ProcessFields(getFormRoot(), "Common.processFieldRequiredHighlighting");

		//Perform any required file attachment validation
		validateNumberOfAttachments(Common.ALLOWED_NUM_ATTACHMENTS, true);
		validateAttachmentFiles(true, true);
		if(getFormSubmissionType()!= null && getFormSubmissionType() == "CTRX"){
		   _checkTotalTransactionAmt(BSAForm.AmountandType.AmountTypes.TotalCashIn, BSAForm.AmountandType.AmountTypes.TotalCashOut);
		}
		if (Common.ERRORS.length > 0) {
			var msg = "There are validation errors:\n\n";
			for (var i=0;i<Common.ERRORS.length;i++) {

				// Only display the first 7 messages (Common.ERRORS[0] - Common.ERRORS[6])
				if (i <= 6) {
					msg += (i+1) + ") " + Common.ERRORS[i] + "\n";
				}
			}

			if (Common.ERRORS.length > 7) {
				msg += "\nMessage limit exceeded. Remaining " + 
					(Common.ERRORS.length - 7) + " validation errors not reported.";
			}
			xfa.host.messageBox(msg);
			valid = false;
		}
		if (valid && Common.ERRORS.length==0 && !Common.isFormSigned() && Common.WARNINGS.length > 0 ){
		    var msg = "There are warnings:\n\n";
			for (var i=0;i<Common.WARNINGS.length;i++) {

				// Only display the first 3 messages				
				if (i <= 3) {
					msg += (i+1) + ") " + Common.WARNINGS[i] + "\n";
				}
			}
			if (Common.WARNINGS.length > 4) {
				 msg += "\nMessage limit exceeded. Remaining " + 
					(Common.WARNING.length - 4) + " warnings not reported.";
			}
		    msg += " Do you wish to continue?";
			var yesNo = xfa.host.messageBox(msg, "Warning", 1, 2);
			if( yesNo == 3 )
			   valid = false;
			else
			   valid = true;
		}
	} catch(ex) {
		Common.VALIDATING = false;
		Common.ERRORS = new Array();
		Common.WARNINGS = new Array();
		valid = false;
	}
	Common.VALIDATING = false;
	Common.ERRORS = new Array();
	Common.WARNINGS = new Array();
	return valid;
}

function docReady() {
	if (Common.checkViewerVersion()) {
		Common.checkReaderFieldHighlighting();
		Common.ProcessFields(getFormRoot(), "Common.processFieldRequiredHighlighting");
		Common.enableDisableSubmitButton(getSubmitButton());

		//Save the current form state
		Common.initialFormValues = xfa.data.saveXML();
	} else {
		//Not a valid viewer version, lock down the form
		Common.lockAllFields(Common.getFormRoot());
	}	
}

function formInitialize() {
	if (Common.getRequiresPIN() && Common.isCBOn(getActionFields().Signed)) {
		//Need to initialize the correct disabled state for the form
		Common.ALL_DISABLED = true;
	}

	//Set state of save status for the form if already signed
	if (Common.getRequiresPIN() && Common.isCBOn(getActionFields().Signed)) {
		Common.savedAfterSigned = true;
	} else {
		Common.savedAfterSigned = false;
	}
}

function preSave() {
	if (Common.isCBOn(getActionFields().Signed)) {
		Common.savedAfterSigned = true;
		Common.enableDisableSubmitButton(getSubmitButton());
	} else {
		Common.savedAfterSigned = false;
	}
}

function postSave() {
	//reset initial values
	Common.initialFormValues = xfa.data.saveXML();
}

function processFieldExit(field) {
	Common.ProcessFields(field, "Common.processFieldRequiredHighlighting");
}

function dropDownEnter(oNode, expandedWidth) {
	//Only do this if the field is enabled
	if (oNode.access == "open") {
		oNode.para.hAlign = "left";
		oNode.w = expandedWidth;
	}
}

function dropDownExit(oNode, width) {
	//Only do this if the field is enabled
	if (oNode.access == "open") {
		dropDownDisplayRawValue(oNode);
		oNode.w = width;
		oNode.para.hAlign = "center";
	}
}

function dropDownInitialize(oNode) {
	dropDownDisplayRawValue(oNode);
}

// This function is used to "trick" designer into displaying the code value instead of the 
// text value for a dropdown option. The code value removes the trailing space from the end
// of the code value so Adobe thinks the value is changed and will display whatever you set.
function dropDownDisplayRawValue(oNode) {
	if (hasValue(oNode)) {
		oNode.rawValue = trim(oNode.rawValue);
	}
}

function processFieldMakeRequired(oNode, sMessage) {
	if (oNode.parent.className == "exclGroup") {
		oNode.parent.validate.nullTest = "error";
		if (sMessage != null) {
			oNode.parent.mandatoryMessage = sMessage;
		}
	} 
	oNode.validate.nullTest = "error";
	if (sMessage != null) {
		oNode.mandatoryMessage = sMessage;
	}
}

function processFieldMakeNotRequired(oNode) {
	if (oNode.parent.className == "exclGroup") {
		oNode.parent.validate.nullTest = "disabled";
	} 
	oNode.validate.nullTest = "disabled";
}

function processFieldMakeRecommended(oNode) {
	if (oNode.parent.className == "exclGroup") {
		oNode.parent.validate.nullTest = "warning";
	} 
	oNode.validate.nullTest = "warning";
}

function processFieldMakeNotRecommended(oNode) {
	if (oNode.parent.className == "exclGroup") {
		oNode.parent.validate.nullTest = "disabled";
	} 
	oNode.validate.nullTest = "disabled";
}

function isCBOn(checkBox) {
	return (checkBox.rawValue == Common.getCBOnValue(checkBox));
}

function isCBOff(checkBox) {
	return (checkBox.rawValue == Common.getCBOffValue(checkBox));
}

function ifCheckedThenEnableOtherField(checkBox, otherField) {
	if (!Common.getRequiresPIN() || !Common.isFormSigned()) {
		var CBOnValue = getCBOnValue(checkBox);
		if (checkBox.rawValue == CBOnValue) {
			otherField.access = "open";
			otherField.validate.nullTest = "error";
			Common.processFieldExit(otherField);
		} else {
			otherField.rawValue = null;
			otherField.validate.nullTest = "disabled";
			Common.processFieldExit(otherField);

			// This property must be set last, b/c the fill color 
			// is only changed if the access is set to "open"
			otherField.access = "readOnly";
		}
	}
}

function copyToolTip(source, destination) {
	destination.assist.toolTip.value = source.assist.toolTip.value; 
}

// iExpectedNumber == -1 indicates unlimited
function validateNumberOfAttachments(iExpectedNumber, addToErrors) {
	var numOfAttachments = getTotalNumOfAttachments();
	var sMessage = "";
	var valid = false;

	if ((iExpectedNumber == numOfAttachments) || iExpectedNumber == -1) {
		valid = true;	
	} else if (iExpectedNumber == 0 && numOfAttachments > 0) {
		message = "Attachments are not allowed for this form. You must delete all attachments before submitting this form.";
		valid = false;	
	} else if (iExpectedNumber == 1 && numOfAttachments == 0) {
		message = "You must attach a file to this form in order to submit. " + DONT_USE_ADOBE_ATT;
		valid = false;
	} else if (iExpectedNumber == 1 && numOfAttachments > 1) {
		message = "You may only attach one file to this form in order to submit. " +
			"You must first use the \"Delete Attachment\" button to delete all of the attachments and " + 
			"then reattach your file using the \"Add Attachment\" button. " + DONT_USE_ADOBE_ATT;
		valid = false;
	}

	if (!valid) {
		if (addToErrors) {
			__setValidationErrorMessage(message);
		} else {
			xfa.host.messageBox(message);
		}
	}
	return valid;
}

//Checks file types and file sizes
function validateAttachmentFiles(deleteMessage, addToErrors) {
	var oDataObjects = event.target.dataObjects;
	var	isValid = true;
	var isBatch = (Common.VALIDATE_ATTACHMENT_FILETYPE == "batch");
	var totalSizeAttachments = 0;

	if (oDataObjects == null || oDataObjects.length < 1) {
		//Nothing to validate
		return true;
	}

	for (var i=0;i<oDataObjects.length;i++) {
		var oDataObject = oDataObjects[i];

		if (oDataObject != null) {
			var sFileName = oDataObject["path"];
			var sMIMEType = oDataObject["MIMEType"];	

			var regEx = new RegExp(BASE_INVALID_FILENAME, "i");
			if (sFileName != null && sFileName != "" && regEx.test(sFileName)) {
				isValid &= false;
			}

			regEx = new RegExp(BATCH_INVALID_FILE_MIME_TYPE, "i");
			if (isValid && isBatch && sFileName != null && sFileName != "" && regEx.test(sFileName)) {
				isValid &= false;
			}

			regEx = new RegExp(BASE_INVALID_FILE_MIME_TYPE, "i");
			if (isValid && sMIMEType != null && sMIMEType != "" && regEx.test(sMIMEType )) {
				isValid &= false;
			}

			regEx = new RegExp(BATCH_INVALID_FILE_MIME_TYPE, "i");
			if (isValid && isBatch && sMIMEType != null && sMIMEType != "" && regEx.test(sMIMEType )) {
				isValid &= false;
			}

			if (!isValid) {
				var sMsg = "This form does not allow this type of file to be attached: \"" + sFileName + "\". ";

				if (isBatch) {
					sMsg += "Only plain text files should be attached to this form. ";
				}

				if (deleteMessage) {
					sMsg += "\nYou must first use the \"Delete Attachment\" button to delete all of the attachments and " + 
					"then re-attach a valid file using the \"Add Attachment\" button. ";
				}

				if (addToErrors) {
					__setValidationErrorMessage(sMsg);
				} else {
					xfa.host.messageBox(sMsg);
				}
			} else {
				var fileSize = oDataObject["size"];

				if (fileSize > MAX_ATTACHMENTS_SIZE_BYTES || (totalSizeAttachments += fileSize) > MAX_ATTACHMENTS_SIZE_BYTES) {
					var sMsg = "The file \'" + sFileName + "\' is too large to be attached to this form. " + 
						"The maximum size for either an individual file or all files attached to this form may not exceed " +
						MAX_ATTACHMENTS_SIZE_TEXT + ".";

					if (addToErrors) {
						__setValidationErrorMessage(sMsg);
					} else {
						xfa.host.messageBox(sMsg);
					}
					return false;
				}
			}
		}
	}
	return isValid;
}

function getTotalNumOfAttachments() {
	var oDataObjects = event.target.dataObjects;
	if (oDataObjects) {
		return oDataObjects.length;
	} else {
		return 0;
	}
}

function _checkTotalTransactionAmt(inField, outField) {
	//For the sake of the testing, treat null/no value as a zero value
	var lCashIn = ((inField.rawValue == null) ? 0 : inField.rawValue);
	var lCashOut = ((outField.rawValue == null) ? 0 : outField.rawValue);
    var cashInOutWarningMsg = "The total amount of the cash in/cash out transaction or aggregated transactions is $10,000 or less which is below the filing threshold requirement.";

    if((lCashIn > 0 && lCashIn <= 10000) || (lCashOut > 0 && lCashOut <= 10000)){
    	__setValidationWarningMessage( cashInOutWarningMsg );
    }
}

function getCountOfSetCheckboxes(parent) {
	var fields = parent.nodes;
	var count=0;

	for (var i=0;i<fields.length;i++) {
		var field = fields.item(i);
		if (field.className == "field" && field.ui.oneOfChild.className == "checkButton") {
			(field.rawValue == getCBOnValue(field)) ? count++ : 0;
		}
	}
	return count;
}

function unsetOtherCheckboxes(currentCB, currentOnVal) {
	var fields = currentCB.parent.nodes;
	for (var i=0;i<fields.length;i++) {
		var field = fields.item(i);
		if (field.className == "field" && field.ui.oneOfChild.className == "checkButton") {
			if (field.rawValue != currentOnVal) {
				field.rawValue = null;
			}
		}
	}
}

function setAllOtherCheckboxes(currentCB, valueToSet) {
	var fields = currentCB.parent.nodes;
	for (var i=0;i<fields.length;i++) {
		var field = fields.item(i);
		if (field.className == "field" && field.ui.oneOfChild.className == "checkButton") {
			if (field != currentCB) {
				if (field.rawValue != valueToSet) {
					field.rawValue = valueToSet;
				}
				//we want to force a change event so they can process the changed value properly
				field.execEvent("change");
			}
		}
	}
}

function getCBOnValue(checkBox) {
	return checkBox.items.nodes.item(0).value;
}

function getCBOffValue(checkBox) {
	return checkBox.items.nodes.item(1).value;
}

function onChangeCBAllowUpTo(checkBox, limit) {
	if (isCBOn(checkBox) && getCountOfSetCheckboxes(checkBox.parent) > limit) {
		xfa.host.messageBox("You may only select up to " + limit + " choices.");
		checkBox.rawValue = getCBOffValue(checkBox);
	}
}

function onChangeCBMutualExcl(checkBox) {
	var currentOnVal= getCBOnValue(checkBox)
	if (checkBox.rawValue == currentOnVal) {
		setAllOtherCheckboxes(checkBox, currentOnVal);
	}
	//Handle field highlighting
	Common.ProcessFields(checkBox.parent, 
		"Common.processFieldRequiredHighlighting");
}

function initMakeMutualExclCheckBoxesRequired(parent, sMessage) {
	var fields = parent.nodes;
	var isFirst = true;
	for (var i=0;i<fields.length;i++) {
		var field = fields.item(i);
		if (field.className == "field" && field.ui.oneOfChild.className == "checkButton") {
			if (isFirst) {
				//Put the message on only one CB so we dont get multiple messages
				isFirst = false;
				processFieldMakeRequired(field, sMessage);
			} else {
				processFieldMakeRequired(field);
			}
		}
	}
}

function initMakeMutualExclCheckBoxesRecommended(parent) {
	var fields = parent.nodes;
	for (var i=0;i<fields.length;i++) {
		var field = fields.item(i);
		if (field.className == "field" && field.ui.oneOfChild.className == "checkButton") {
			processFieldMakeRecommended(field);
		}
	}
}

function initMakeMutualExclCheckBoxesNotRequired(parent) {
	var fields = parent.nodes;
	for (var i=0;i<fields.length;i++) {
		var field = fields.item(i);
		if (field.className == "field" && field.ui.oneOfChild.className == "checkButton") {
			processFieldMakeNotRequired(field);
		}
	}
}

//Strips the date of the time by return a new Date object with just the date set
function removeTimeFromDate(theDate) {
	if (theDate != null) {
		return new Date(theDate.getFullYear(), theDate.getMonth(), theDate.getDate());
	} else {
		return theDate;
	}
}

//Makes sure date is not greater than today, 
//and optionally not less than the date passed to the function - do not call directly from a validate function
function __validateDateValueRange(dateField, dateFormat, notLessThanDate, notGreaterThanDate, useFormattedValue) {
	var isValid = true;
	var currentDateVal = null;
	var usingFormatted = (useFormattedValue != null && useFormattedValue == true);

	if (usingFormatted) {
		valueToTest = dateField.formattedValue;
	} else {
		valueToTest = dateField.rawValue;
	}

	//if it is a special response, it is always valid
	if (!(new RegExp(UNKNOWN_DATE_REGEX).test(valueToTest))) {
		try {
			if (valueToTest != null && valueToTest != "") {
				currentDateVal = util.scand(dateFormat, valueToTest);
			}
		} catch (e) {
			currentDateVal = null;
		}

		//Important to remove the time portion of the dates so
		//we only compare the dates themselves
		var today = new Date();

		if (currentDateVal != null) {
			if (Common.removeTimeFromDate(currentDateVal) > Common.removeTimeFromDate(today)) {
				isValid = false;
			} else {
				//optionally check not less than date here
				if (notLessThanDate!= null) {
					isValid = (Common.removeTimeFromDate(currentDateVal) >= Common.removeTimeFromDate(notLessThanDate));	
				}

				//optionally check not greater than date here
				if (isValid && notGreaterThanDate!= null) {
					isValid = (Common.removeTimeFromDate(currentDateVal) <= Common.removeTimeFromDate(notGreaterThanDate));
				}
			}
		} else {
			isValid = false;
		}
	}
	return isValid;
}

function validateDateValue(dateField, validDatePatternsArray, notLessThanDate, notGreaterThanDate) {
	var isValid = __validateDateValue(dateField, validDatePatternsArray, notLessThanDate, notGreaterThanDate);
	return Common.processFieldValidity(dateField, isValid);
}


function __validateDateValue(dateField, validDatePatternsArray, notLessThanDate, notGreaterThanDate) {
	var isValid = true;
	if (dateField.rawValue != null && dateField.rawValue != "") {
		isValid = __validateFieldValue(dateField, validDatePatternsArray, null, true);

		if (isValid) {
			isValid = __validateDateValueRange(dateField, "yyyy-mm-dd", notLessThanDate, notGreaterThanDate);
		}
	}
	return isValid;
}

function validateSpecialResponseDateValue(dateField, dateBindField, unknownValueRespose, notLessThanDate, notGreaterThanDate) {
	var isValid = true;
	var today = new Date();
	var formattedValue = dateField.formattedValue;

	if (formattedValue != null && formattedValue != "") {
		if (formattedValue != unknownValueRespose) {
			isValid = (new RegExp(FORMATTED_DATE_REGEX).test(formattedValue));
			if (isValid) {
				isValid = __validateDateValueRange(dateField, "mm/dd/yyyy", notLessThanDate, notGreaterThanDate, true);
			} else {
				//Try the special response formats
				isValid = (new RegExp(FORMATTED_DATE_WITH_ZEROS_REGEX).test(formattedValue));
				if (isValid) {
					//Now it gets tricky, need to validate as much of the date as possible -
					//replace 00's with current day and/or month - it is in the form mm/dd/yyyy
					var split = formattedValue.split("/");
					var month = split[0];
					var day = split[1];
					var year = split[2];			

					//Check not greater than the current year
					if (parseInt(year) > parseInt(today.getFullYear())) {
						isValid = false;
					}				

					//Can only validate the month if the year is the current year
					if (isValid && (month != "00" && (parseInt(year) == parseInt(today.getFullYear())))) {
						isValid = (parseInt(month) <= (parseInt(today.getMonth()) + 1));
					}

					//Optional: compare to not less than date's year/month
					if (isValid && notLessThanDate != null) {
						if (parseInt(year) < parseInt(notLessThanDate.getFullYear())) {
							isValid = false;
						} else if (month != "00" && (parseInt(year) == parseInt(notLessThanDate.getFullYear()))) {
							isValid = (parseInt(month) >= (parseInt(notLessThanDate.getMonth()) + 1));
						}
					}

					//Optional: compare to not greater than date's year/month
					if (isValid && notGreaterThanDate!= null) {
						if (parseInt(year) > parseInt(notGreaterThanDate.getFullYear())) {
							isValid = false;
						} else if (month != "00" && (parseInt(year) == parseInt(notGreaterThanDate.getFullYear()))) {
							isValid = (parseInt(month) <= (parseInt(notGreaterThanDate.getMonth()) + 1));
						}
					}
				}
			}
		}
	}

	//Set the value into the bind field if it is valid
	if (isValid) {
		setDateBindField(dateBindField, formattedValue, unknownValueRespose);
	} else {
		setDateBindField(dateBindField, null, unknownValueRespose);
	}
	return Common.processFieldValidity(dateField, isValid);
}  

function setDateBindField(dateBindField, currentVal, unknownValueRespose) {
	var newValue = null;

	if (currentVal != null && currentVal != "") {
		if (currentVal == unknownValueRespose) {
			newValue = currentVal;
		} else {
			var split = currentVal.split("/");
			// mm/dd/yyyy formatted, convert to MMDDYYY
			newValue = split[0] + split[1] + split[2];	
		}
	}
	dateBindField.rawValue = newValue;
}

function getUserSiteWarning(submitUrl, userSiteWarning) {
   if (submitUrl.indexOf("bsaefiling.fincen.gov") == -1 && submitUrl.indexOf("bsa-efile-test") == -1) {
      userSiteWarning.rawValue = "This PDF is intended for testing purpose only. Please do not use it in a production environment."; 
   }
   else {
 	  userSiteWarning.rawValue="";
   }
}

function validateFromToDateFields(fromDate, toDate, isFromDate, notLessThanDate) {
	var dateField = (isFromDate) ? fromDate : toDate;
	var isValid = __validateDateValue(dateField, new Array(Common.DATE_REGEX), notLessThanDate);
	if (isValid) {
		if (fromDate.rawValue != null && toDate.rawValue != null) {
			var startDate = util.scand("yyyy-mm-dd", fromDate.rawValue);
			var endDate = util.scand("yyyy-mm-dd", toDate.rawValue);
			if (startDate > endDate) {
				isValid = false;
			}
		}
	}
	return Common.processFieldValidity(dateField, isValid);
}

//Replaces all special MS Word characters with ASCII equivalents
function replaceAllSpecialCharacters(node, displayMsg) {
	if (node.access != "open" || !Common.hasValue(node)) {
		return;
	}

	var regEx = new RegExp(SPECIAL_CHAR_REGEX, "g");

	//test to see if we have any special chars to replace
	if (regEx.test(node.rawValue)) {	
		var original = node.rawValue;
		var originalLen = original.length;
		var v = new String(node.rawValue);
		var regex = {};

		for (key in SPECIAL_CHAR_REPLACEMENTS) {
    		regex[key] = new RegExp(key, 'g');
		}

	    for (key in SPECIAL_CHAR_REPLACEMENTS) {
    	    v = v.replace(regex[key], SPECIAL_CHAR_REPLACEMENTS[key]);
    	}

		node.rawValue = v;
		var maxNumChars = node.value.text.maxChars;

		if (v.length > maxNumChars) {
			xfa.host.messageBox("Some special characters have been replaced by equivalent ASCII characters and as a result some information may have been truncated. " +
				"Please verify that the field contains all of the required information and edit as needed. " +
				"This may have happened because you pasted in the text that contained special characters from a rich text " + 
				"or publishing tool (such as Microsoft Word).");
		} else if (displayMsg == true && v != original) {
			xfa.host.messageBox("Some special characters have been replaced by equivalent ASCII characters. " + 
				"This may have happened because you pasted in the text from a rich text or publishing tool (such as Microsoft Word). " + 
				"Please review the text before you submit the data.");
		}
	}
}

//Processes large text field (narrative) for invalid characters
function processNarrativeText(narrative, narrativeFieldName) {
	var valid = true;
	if (narrative.access != "open" || !Common.hasValue(narrative)) {
		return valid;
	}

	//First replace all known special characters
	replaceAllSpecialCharacters(narrative);
	var val = new String(narrative.rawValue);
	var regEx = new RegExp(INVALID_CHARS_REGEX, "g");
	var result;

	var msg = "";
	var counter = 0;
	while ((result = regEx.exec(val)) != null) {
		counter++;

		//Replace invalid character with a '?' character
		var pos = Math.max(0, result.index);
		var end = Math.min(val.length, pos + 1);
		val = val.substring(0, pos) + "?" + val.substring(end);
	}

	if (counter > 0) {
		valid = false;
		narrative.rawValue = val;
		xfa.host.messageBox("Invalid and/or special characters have been found in the " 
			+ ((narrativeFieldName != null) ? narrativeFieldName : "narrative") + " field. " + 
			"These characters have been replaced with the \'?\' character. Please review the text and edit as needed.");
	}
	return valid;
}

//Valdates a text field for invalid characters
function validateTextField(node) {
	var valid = true;
	if (node.access != "open" || !Common.hasValue(node)) {
		return valid;
	}

	//First replace all known special characters
	replaceAllSpecialCharacters(node);
	var val = node.rawValue;
	var regEx = new RegExp(INVALID_CHARS_REGEX, "g");

	if (regEx.test(val)) {
		valid = false;
	}
	return Common.processFieldValidity(node, valid);
}

//
// Please note: this is a workaround for an Adobe bug where getting/setting
// a comb field's background color is causing a reader extended form to become
// invalid after a save. This workaround function should be placed in the 
// initialize event of the comb field.
//
function combFieldInit(oNode) {
	var uiNode = oNode.ui.oneOfChild;
	if (uiNode.border != null) {
		var currentColor = uiNode.border.fill.color.value;
		uiNode.border.fill.color.value = currentColor;
	}
}            

//Call this on NON-MUTUALLY EXCLUSIVE checkboxes only
function initRequiredCheckboxes(parent, emptyMessage) {
	if (Common.isFormSigned()) {
		//Don't change if signed
		return;
	}
	Common.initMakeMutualExclCheckBoxesRequired(parent, emptyMessage);
	//Some could already be checked, so process requiredness
	Common.processCheckboxRequiredness(parent);
}

//Call this on NON-MUTUALLY EXCLUSIVE checkboxes only
function initRecommendedCheckboxes(parent) {
	if (Common.isFormSigned()) {
		//Don't change if signed
		return;
	}
	Common.initMakeMutualExclCheckBoxesRecommended(parent);
	//Some could already be checked, so process recommendedness
	Common.processCheckboxRecommendedness(parent);
}

//Call this on NON-MUTUALLY EXCLUSIVE checkboxes only
function processCheckboxRequiredness(parent) {
	Common._processCheckboxRecommendedOrRequiredness(parent, true);
}            

//Call this on NON-MUTUALLY EXCLUSIVE checkboxes only
function processCheckboxRecommendedness(parent) {
	Common._processCheckboxRecommendedOrRequiredness(parent, false);
} 

function _processCheckboxRecommendedOrRequiredness(parent, isRequired) {
	if (Common.isFormSigned()) {
		//Don't change if signed
		return;
	}

	var boxesAreChecked = false;
	var fields = parent.nodes;
	// Determine whether or not any boxes are checked.
	for (var i=0;i<fields.length;i++) {
		var field = fields.item(i);
		if (field.className == "field" && field.ui.oneOfChild.className == "checkButton") {
			if(Common.isCBOn(field)){
				boxesAreChecked = true;
				break;
			}
		}
	}
	// If any boxes are checked, make the boxes not required/recommended. Otherwise, make them required.recommended.
	for (var i=0;i<fields.length;i++) {
		var field = fields.item(i);
		if (field.className == "field" && field.ui.oneOfChild.className == "checkButton") {
			if (boxesAreChecked) {
				isRequired ? Common.processFieldMakeNotRequired(field) : Common.processFieldMakeNotRecommended(field);
			} else {
				isRequired ? Common.processFieldMakeRequired(field) : Common.processFieldMakeRecommended(field);
			}
		}
	}
	Common.ProcessFields(parent, "Common.processFieldRequiredHighlighting");
} 

//validate the identification fields when Other is XX.
function validateIdentification(identificationData, identificationDocOther) {
	var valid = true;
	var numberValid = true;
	var issuerValid = true;

	if (Common.hasValue(identificationDocOther) && Common.trim(identificationDocOther.rawValue).toUpperCase() == "XX") {
		var number = (Common.hasValue(identificationData.IdentificationNumber)) ? Common.trim(identificationData.IdentificationNumber.rawValue).toUpperCase() : "";
		var issuer = (Common.hasValue(identificationData.IdentificationIssuer)) ? Common.trim(identificationData.IdentificationIssuer.rawValue).toUpperCase() : "";

		if (number == "XX" && issuer == "XX") {
			valid = false;
			numberValid = false;
			issuerValid = false;
		} 
	}

   	//Only highlight the fields - we do not want their field-specific error messages in the list of errors.
	Common.processFieldValidityUI(identificationData.IdentificationNumber, numberValid); 
   	Common.processFieldValidityUI(identificationData.IdentificationIssuer, issuerValid);

	// If invalid, we want the validateFields message to be added to the list of errors
   	return Common.processFieldValidity(identificationData, valid, true);
}

//Checks if the identification fields are required when Other is XX
function checkIdentificationRequired(identificationData, identificationDocOther) {
	if (Common.hasValue(identificationDocOther) && Common.trim(identificationDocOther.rawValue).toUpperCase() == "XX") {
		var number = (Common.hasValue(identificationData.IdentificationNumber)) ? Common.trim(identificationData.IdentificationNumber.rawValue).toUpperCase() : "";
		var issuer = (Common.hasValue(identificationData.IdentificationIssuer)) ? Common.trim(identificationData.IdentificationIssuer.rawValue).toUpperCase() : "";

		if (Common.hasValue (identificationData.IdentificationNumber) && Common.hasNoValue(identificationData.IdentificationIssuer)) {
			Common.processFieldMakeRequired(identificationData.IdentificationIssuer);
		} else if (Common.hasValue(identificationData.IdentificationIssuer)&& Common.hasNoValue(identificationData.IdentificationNumber)) {
			Common.processFieldMakeRequired(identificationData.IdentificationNumber);
		} else {
			Common.processFieldMakeNotRequired(identificationData.IdentificationIssuer);
			Common.processFieldMakeNotRequired(identificationData.IdentificationNumber);
		}
		Common.processFieldRequiredHighlighting(identificationData.IdentificationIssuer);
		Common.processFieldRequiredHighlighting(identificationData.IdentificationNumber);
	}
}

