// Should be called when exiting the country field // Accepted values for requiredness parameter are "Required", "Recommended", or "Optional" // setToXXIfNoStatesDefined may be removed once all the forms have this functionality. function setStates(oCountryDropdown, oStateDropdown, requiredness, addBlankAtTop, setToXXIfNoStatesDefined) {
//Don't do this if the form is already signed (locked down) if (Common.isFormSigned()) { return; }
if(( arguments.length < 3 ) || ( requiredness != "Required" && requiredness != "Recommended" && requiredness != "Optional" )) { requiredness = "Required"; }
if( arguments.length < 4 ) { addBlankAtTop = false; }
if (arguments.length < 5) { setToXXIfNoStatesDefined = false; }
if(!countryHasChanged(oCountryDropdown)) { return; }
oStateDropdown.clearItems(); oStateDropdown.rawValue = null;
if(addBlankAtTop) { oStateDropdown.addItem("",""); }
// Get the array of states associated with the selected country display value. var aStates; if( countryIsUS(oCountryDropdown) || !Common.hasValue(oCountryDropdown ) ) { aStates = oStates["United States of America"]; } else { aStates = oStates[ oCountryDropdown.getDisplayItem(oCountryDropdown.selectedIndex) ]; }
// If there are states associated with a country, use them to populate the state dropdown. if(aStates && aStates.length) { //Enable state dropdown oStateDropdown.access = "open";
// Add each state to the dropdown for(var i=0;i < aStates.length; i++) { //first param is display value, second is bound value oStateDropdown.addItem( aStates[i][0], aStates[i][1] + " "); }
// Set field's requiredness. if(requiredness == "Required") { Common.processFieldMakeRequired(oStateDropdown); } else if (requiredness == "Recommended") { Common.processFieldMakeRecommended(oStateDropdown); } else if (requiredness == "Optional") { Common.processFieldMakeNotRequired(oStateDropdown); }
Common.ProcessFields(oStateDropdown, "Common.processFieldRequiredHighlighting");
} else { // There were no states associated with the selected country. // Enable the dropdown b/c the highlighting only works on enabled fields. oStateDropdown.access = "open";
if(setToXXIfNoStatesDefined){ oStateDropdown.addItem( "XXX","XXX"); oStateDropdown.rawValue = "XXX"; oStateDropdown.para.hAlign = "center"; }
// Make the state dropdown optional Common.processFieldMakeNotRequired(oStateDropdown);
// Set the field's highlighting Common.ProcessFields(oStateDropdown, "Common.processFieldRequiredHighlighting"); disableAndResetFields(oStateDropdown); // After highlighting has been performed, disable the dropdown. oStateDropdown.access = "nonInteractive"; } }
