function countryHasChanged(oCountryDropdown) {
var countryHasChanged = false;
//Remove space from end of new country code and original country code. Original country code was set upon entry into the CountryDropdown field. var newDropDownValue = oCountryDropdown.rawValue; newDropDownValue != null? newDropDownValue = Common.trim(newDropDownValue): newDropDownValue = "";
var oldDropDownValue = originalDropDownValue; oldDropDownValue != null? oldDropDownValue = Common.trim(oldDropDownValue): oldDropDownValue = "";
// No need to reset states if the country value has not changed. if ( oldDropDownValue == "" && newDropDownValue =="US" ) { //no change } else if( newDropDownValue != oldDropDownValue) { countryHasChanged = true; }
return countryHasChanged; }
