// Checks if the country is US. The country is US if the value is "US" or blank/null b/c the country is // always assumed to be US unless explicitly changed. function countryIsUS(oCountryField) { //Remove space from end of country code var countryValue = (oCountryField.rawValue == null) ? "" : Common.trim(oCountryField.rawValue); return (countryValue == "US"); }
