// If this is a foreign country and foreign postal codes are allowed, // we perform a more relaxed validation on the ZIP code field. function validateZIP(zipField, countryField) { if (StatesAndCountriesJS.countryIsUS(countryField)) { return Common.validateFieldValue( zipField, new Array(Common.ZIP_REGEX_XX), new Array(Common.ZIP_REGEX_INVALID)); } else { return Common.validateFieldValue(zipField, new Array(Common.FOREIGN_POSTAL_CODE)); } }
