 function processCBDependsOnAnother(checkBox, otherField) {
 if (Common.isFormSigned()) {
		//Don't change if signed
		return;
	}

	if (Common.isCBOn(checkBox)) {
		Common.processFieldMakeRequired(otherField);
	  	Common.processFieldExit(otherField);
	} else { 
		Common.processFieldMakeNotRequired(otherField);
	  	Common.processFieldExit(otherField);
	}
 }

 function enableOtherField(otherField) {
	if (Common.isFormSigned()) {
		//Don't change if signed
		return;
	} 
		otherField.access = "open";
		otherField.validate.nullTest = "error";
		Common.processFieldExit(otherField);
} 

function disableOtherField(otherField) {
		otherField.validate.nullTest = "disabled";
		BSACommon.disableAndResetFields(otherField); 
} 

function ifCheckedMakeRequired(oField, otherField) {
	if (Common.isFormSigned()) {
		//Don't change if signed
		return;
	}
	if (Common.isCBOn(oField)) {
		Common.processFieldMakeRequired(otherField);
	}
	else {
		Common.processFieldMakeNotRequired(otherField);
	}
	Common.processFieldRequiredHighlighting(otherField);
}     
function validateZIP(zipField, countryField) {
	if (StatesAndCountriesJS.countryIsUS(countryField)) {
		return Common.validateFieldValue(zipField, new Array(Common.ZIP_REGEX), new Array(Common.ZIP_REGEX_INVALID));
	} else {
		return Common.validateFieldValue(zipField, new Array(BSACommon.FOREIGN_POSTAL_CODE));
	}
}

function validateTIN(TINField, TinType) {
	if (TINField.rawValue == null) {
		return;
	}
	if (BSACommon.TINIsUS(TinType)) {
		return Common.validateFieldValue(TINField, new Array(Common.SSN_REGEX), new Array(BSACommon.SSN_REGEX_INVALID));
	} else if (BSACommon.TINIsForeign(TinType)){
		return Common.validateFieldValue(TINField, new Array(BSACommon.SSN_FOREIGN_REGEX));
	}
}

function validateDOB(dateField, dateOfBirthBindField, dateOfTransaction) {
	var minDOBDateVal = getMinDOBDate() ;
	if (Common.hasValue(dateField)) {
		if (Common.hasValue(dateOfTransaction)) {
			var dateOfTransactionVal = util.scand("yyyy-mm-dd", dateOfTransaction.rawValue);
			return Common.validateSpecialResponseDateValue(dateField, dateOfBirthBindField, null, minDOBDateVal, dateOfTransactionVal);
		} else {
			return Common.validateSpecialResponseDateValue(dateField, dateOfBirthBindField, null, minDOBDateVal, null);
		}
	}
}

