function enableDisableSubformsWithCheckBoxes(proxyCB, subform, enableFlag) {
	if ( enableFlag == false ) {
		BSACommon.disableAndResetFields(subform);
		Common.enableField(proxyCB);
		proxyCB.rawValue = Common.getCBOnValue(proxyCB); 
	}
	else {
		Common.enableFields(subform);
		proxyCB.rawValue = null; 
		BSACommon.setButtonsColor(subform);
	}
	Common.processCheckboxRequiredness(subform); 
} 


function onChangeSetAllOtherCBs(currentCB) {
	var fields = currentCB.parent.nodes;
	var isCurrentCBOn = Common.isCBOn(currentCB);

	for (var i=0;i<fields.length;i++) {
		var field = fields.item(i);
		if (field.className == "field" && field.ui.oneOfChild.className == "checkButton") {
			if (field != currentCB) {				   
				if( isCurrentCBOn) {
					field.rawValue = Common.getCBOffValue(field);
				}

				//we want to force a change event so they can process the changed value properly
				field.execEvent("change");
			}
		}
	}
}

function processthirdParty (checkBox,thirdParty,signatureTitle) {
	if (Common.isFormSigned()) {
		//Don't change if signed
		return;
	}
	if (Common.isCBOn(checkBox)) {
		Common.processFieldMakeRequired(thirdParty.ThirdPartySub.PreLastName);
		Common.processFieldMakeRequired(thirdParty.Namesub.PreFirstname);
		Common.processFieldMakeRequired(thirdParty.Namesub.TIN);
		Common.processFieldMakeRequired(thirdParty.Namesub.TINTYPE);
		Common.processFieldMakeRequired(thirdParty.CitySub.ZIP);
		Common.processFieldMakeRequired(thirdParty.CitySub.State);
		Common.processFieldMakeRequired(thirdParty.CitySub.Country);
		Common.processFieldMakeRequired(thirdParty.Namesub.FirmName);
		Common.processFieldMakeRequired(thirdParty.AddSub.FirmEIN);
		Common.processFieldMakeRequired(thirdParty.AddSub.TINTYPE);
		Common.enableFields(thirdParty);
		if ( Common.hasValue(thirdParty.CitySub.Country) ) {    
			if (!StatesAndCountriesJS.countryIsUSCAMX(thirdParty.CitySub.Country) ) { 
				Common.processFieldMakeNotRequired(thirdParty.CitySub.State);
				BSACommon.disableAndResetFields(thirdParty.CitySub.State); 
			}
		}
		BSACommon.ifCheckedThenDisableOtherField(checkBox,signatureTitle,true);
	}
	else {
		BSACommon.ifCheckedThenDisableOtherField(checkBox,signatureTitle,true);
		Common.processFieldMakeNotRequired(thirdParty.ThirdPartySub.PreLastName); 
		Common.processFieldMakeNotRequired(thirdParty.Namesub.PreFirstname);
		Common.processFieldMakeNotRequired(thirdParty.Namesub.TIN);
		Common.processFieldMakeNotRequired(thirdParty.Namesub.TINTYPE);
		Common.processFieldMakeNotRequired(thirdParty.CitySub.State);
		Common.processFieldMakeNotRequired(thirdParty.CitySub.ZIP);
		Common.processFieldMakeNotRequired(thirdParty.CitySub.Country);
		Common.processFieldMakeNotRequired(thirdParty.Namesub.FirmName);
		Common.processFieldMakeNotRequired(thirdParty.AddSub.FirmEIN);
		Common.processFieldMakeNotRequired(thirdParty.AddSub.TINTYPE);
		BSACommon.disableAndResetFields(thirdParty);
	}

}

