function makePartRequired(MaxAcctValue,MaxAccntUnknown,AccountType,FIAcctName,AcctNumber,Address,City, State,ZIP,Country,NoJointOwner) {
	if (Common.isFormSigned()) {
	//Don't change if signed
		return;
	}
	/*if (MaxAcctValue.rawValue == 0) {
		MaxAcctValue.rawValue = null;
	}*/
	if (MaxAcctValue.rawValue != null ||  MaxAcctValue.rawValue == 0 || Common.isCBOn(MaxAccntUnknown ) 
		|| AccountType.rawValue !=null || FIAcctName.rawValue != null || AcctNumber.rawValue!=null 
		|| Address.rawValue !=null || City.rawValue!= null || State.rawValue != null  || ZIP.rawValue != null || Country.rawValue !=null
		||(NoJointOwner != null && NoJointOwner.rawValue!=null) ){
		Common.processFieldMakeRequired(FIAcctName);
		Common.processFieldMakeRequired(AccountType);
		Common.processFieldMakeRequired(AcctNumber);
		Common.processFieldMakeRequired(Country);
		if (NoJointOwner != null )
			Common.processFieldMakeRequired(NoJointOwner);
		if (!Common.isCBOn(MaxAccntUnknown)) {
			Common.processFieldMakeRequired(MaxAcctValue);
		}
	}
	else {
		Common.processFieldMakeNotRequired(FIAcctName);
		Common.processFieldMakeNotRequired(AccountType);
		Common.processFieldMakeNotRequired(AcctNumber);
		Common.processFieldMakeNotRequired(Country);
		Common.processFieldMakeNotRequired(MaxAcctValue);
		if (NoJointOwner != null )
			Common.processFieldMakeNotRequired(NoJointOwner);
	}
	Common.processFieldRequiredHighlighting(FIAcctName);
	Common.processFieldRequiredHighlighting(AccountType);
	Common.processFieldRequiredHighlighting(AcctNumber);
	Common.processFieldRequiredHighlighting(Country);
	Common.processFieldRequiredHighlighting(MaxAcctValue);
	if (NoJointOwner != null )
		Common.processFieldRequiredHighlighting(NoJointOwner);
}

function ifOneThenDisableOtherField(field1, otherField, notRequired) {
	if (Common.isFormSigned()) {
		//Don't change if signed
		return;
	}
	if ( field1.rawValue == null ) {
		otherField.access = "open"; 
		if ( !notRequired) {
			otherField.validate.nullTest = "error"; 
		}
		Common.processFieldExit(otherField);
	} else { 
		otherField.validate.nullTest = "disabled";
		BSACommon.disableAndResetFields(otherField); 
	}
}
function ifTwoThenDisableOtherField(field1, field2, otherField, notRequired) {
	if (Common.isFormSigned()) {
		//Don't change if signed
		return;
	}
	if (( field1.rawValue == null ) && (field2.rawValue == null) ){
		otherField.access = "open"; 
		if ( !notRequired) {
			otherField.validate.nullTest = "error"; 
		}
		Common.processFieldExit(otherField);
	} else { 
		otherField.validate.nullTest = "disabled";
		BSACommon.disableAndResetFields(otherField); 
	}
}
function launchInstructions() {
	var instructionPath = Common.getFormInstructionPath(); 
	instructionPath += "fbar_instructions.htm"; 
 	app.launchURL(instructionPath, true);
}
function trimField(field) {
	var regEx = new RegExp(ALL_SPACES, "g");
	if (Common.hasValue(field) && regEx.test(field.rawValue)) {
		field.rawValue = Common.trim(field.rawValue);
	}
	return field.rawValue;
}

function processConsolidated(typeOfFiler,firstName,middleName,suffix,Dob) {
	if (!Common.isFormSigned()) {
		if ((typeOfFiler.rawValue == "C") || (typeOfFiler.rawValue == "D")) {
			Common.processFieldMakeNotRequired(firstName); 
			Common.processFieldMakeNotRequired(Dob); 
	    	BSACommon.disableAndResetFields(firstName);
	    	BSACommon.disableAndResetFields(middleName);
	    	BSACommon.disableAndResetFields(suffix);
	    	BSACommon.disableAndResetFields(Dob);

		}
		else {
			Common.enableFields(firstName);
			Common.enableFields(middleName);
			Common.enableFields(suffix);
			Common.enableFields(Dob);

		} 
	}
}

