	if (Common.hasValue(CalYear)) { 
		validateField.rawValue = CalYear.rawValue + "-01-01";
		var valid = Common.validateDateValue(validateField, new Array(Common.DATE_REGEX));
	//	if ( !valid ) {
		//	xfa.host.messageBox("Item 1 - Calendar year is not valid. It must be in the format of YYYY, e.g., 2013.");
		//}
		return Common.processFieldValidity(CalYear, valid);
	}
}
function acctValidate(acctField) {
	if (Common.hasValue(acctField)) { 
		var valid = Common.validateFieldValue(acctField, new Array(FFBAR.ACCT_REGEX));
		if (acctField.rawValue < 25) {
			valid = false;
		}
		return Common.processFieldValidity(acctField, valid);
	}
}
function jointOwnerValidate(ownerField) {
	if (Common.hasValue(ownerField)) { 
		var valid = Common.validateFieldValue(ownerField, new Array(FFBAR.NUM3_REGEX));
		return Common.processFieldValidity(ownerField, valid);
