function processSubmitButtonClick(oNode){
	//Check if we are submitting from within the browser
	if (!event.target.external) {
		xfa.host.messageBox("You must first log in to the BSA E-Filing application in order to submit this form. " +
							"Once logged in, you may then re-open this form and submit.");
		return;
	}

	if (Common.checkViewerVersion()) {
		var valid = true;
		var resetSubmitting = true;

		if (oNode.parent.Submitting.rawValue == "1") {
			xfa.host.messageBox("You may have hit the Submit button more than one time. " + 
				"Please wait until the form finishes submitting and you see the application confirmation page.");
			valid = false;
			resetSubmitting = false;
		}

		//We need to make sure that the button cannot be clicked more than once
		oNode.presence = "invisible";
		oNode.parent.Submitting.rawValue = "1";

		if (valid && !Common.processFormValidation()) {
			xfa.host.messageBox("This form has errors that need to be corrected before submitting.");
			valid = false;
		}

		if (valid && Common.getRequiresPIN() && Common.getActionFields().Signed.rawValue != 1) {
			xfa.host.messageBox("You must sign this form before submitting.");
			valid = false;
		}

		// Determine whether the form data has changed.
		if(valid && Common.initialFormValues != xfa.data.saveXML()){
			xfa.host.messageBox("Form has changed. You must save this form before submitting.");
			valid = false;
		}

		//Submit
		if (valid) {
			try {		
				var additionalParameters = "";
				if (Common.getActionFields() != null) {
					additionalParameters = "&SUBMISSION_VALUE=" 
						+ Common.getActionFields().PINHash.rawValue;
				}			

				var fullURL = Common.getFormSubmissionURL() + "?SUBMISSION_TYPE=" + 
							  Common.getFormSubmissionType() + "&SUBMISSION_NAME=" +
							  encodeURIComponent(Common.getFormSubmissionName()) + 
						      "&NUM_FORMS=" + Common.getNumFormsReported() +
							  additionalParameters;

				if (DEBUG.value == "true") {
					xfa.host.messageBox("Submit URL = " + fullURL );
				}

				oNode.parent.HTTPSubmit.resolveNode("#event.submit").setAttribute(fullURL, "target");
				oNode.parent.Submitted.rawValue = "1";
				oNode.parent.HTTPSubmit.execEvent("click");
			} catch (e) {
			}
		} else {
			// Not a valid submit, show the button again
			oNode.presence = "visible";
			if (resetSubmitting) {
				oNode.parent.Submitting.rawValue = "0";
			}
		}
	}
}

