function ifCheckedThenDisableOtherField(checkBox, otherField, notRequired) {
	if (Common.isFormSigned()) {
		//Don't change if signed
		return;
	}

	if (!Common.isCBOn(checkBox)) {
		otherField.access = "open"; 
		if ( !notRequired) {
			otherField.validate.nullTest = "error"; 
		}
		Common.processFieldExit(otherField);
	} else { 
		otherField.validate.nullTest = "disabled";
		BSACommon.disableAndResetFields(otherField); 
	}
}

function isDisabled(field) {

	if (field.access == "readOnly" || field.access == "nonInteractive") {
		return true;
	}
	return false;	
}            


function ifCheckedThenEnableOtherField(checkBox, otherField) {
	if (!Common.getRequiresPIN() || !Common.isFormSigned()) {
		var CBOnValue = Common.getCBOnValue(checkBox);
		if (checkBox.rawValue == CBOnValue) {
			otherField.access = "open";
			otherField.validate.nullTest = "error";
			Common.processFieldExit(otherField);
		} else {
			otherField.validate.nullTest = "disabled";
			BSACommon.disableAndResetFields(otherField);
		}
	}
}       

function TINIsForeign(oTINField) {
	//Remove space from end
	var TINValue = (oTINField.rawValue == null) ? "" : Common.trim(oTINField.rawValue);
	return (TINValue == "C");
}            

function TINIsUS(oTINField) {
	//Remove space from end
	var TINValue = (oTINField.rawValue == null) ? "" : Common.trim(oTINField.rawValue); 
	return (TINValue == "A" || TINValue == "B");
}            

function ifCheckedThenMakeNotRequired(checkBox, otherField) {

	if (Common.isFormSigned()) {
		//Don't change if signed
		return;
	}

	if (!Common.isCBOn(checkBox)) {
		Common.processFieldMakeRequired(otherField);
	  	Common.processFieldExit(otherField);
	} else { 
		Common.processFieldMakeNotRequired(otherField);
	  	Common.processFieldExit(otherField);
	}
}            


function validateTIN(TINField, TinType) {
	if (TINField.rawValue == null) {
		return true;
	}	

	if ( Common.validateFieldValue(TINField, new Array(SSN_FOREIGN_REGEX), new Array(TIN_FOREIGN_REGEX_INVALID))) {	
	  if (TINIsUS(TinType)) {
		return Common.validateFieldValue(TINField, new Array(Common.SSN_REGEX), new Array(SSN_REGEX_INVALID));
	  }
	  else {
	  	return true;
	  }
	}
	else {
		return false;
	}
}   

function getTotalAmtForCashInOutLocation(fieldName){
	var total = 0;
	for (var nPageCount = 0; nPageCount < xfa.host.numPages; nPageCount++) { 

    	var oFields = xfa.layout.pageContent(nPageCount, "field"); 
    	var nNodesLength = oFields.length; 

    	for (var nNodeCount = 0; nNodeCount < nNodesLength; nNodeCount++) { 
        	if (oFields.item(nNodeCount).name == fieldName) { 
        		if(oFields.item(nNodeCount).rawValue != null){
            		total = total + oFields.item(nNodeCount).rawValue;
            	} else {
            		oFields.item(nNodeCount).rawValue = 0;
            	}  
             }                
        } 

    } 
    return total;
}

function validateCashInOut(cashIn, cashOut){
		for (var nPageCount = 0; nPageCount < xfa.host.numPages; nPageCount++) { 

    	var oFields = xfa.layout.pageContent(nPageCount, "field"); 
    	var nNodesLength = oFields.length; 

    	for (var nNodeCount = 0; nNodeCount < nNodesLength; nNodeCount++) { 
        	if (oFields.item(nNodeCount).name == cashIn && oFields.item(nNodeCount + 1).name == cashOut) { 
        		if((oFields.item(nNodeCount).rawValue == null || oFields.item(nNodeCount).rawValue == 0)&& (oFields.item(nNodeCount + 1).rawValue == null || oFields.item(nNodeCount + 1).rawValue == 0)){
            		return false;
            	} 
            }                
        } 

    } 
    return true;
}
