function __internalEnableField(oNode) {
	if (oNode) {
		//Check to see if this should remain R/O, protected or non-interactive
		var fieldFillColor = Common.getFillColor(oNode);

		if ((fieldFillColor != Common.DISABLED_FIELD_COLOR_STATE_RO && fieldFillColor != Common.NORMAL_FIELD_COLOR_STATE_RO) &&
			(fieldFillColor != Common.DISABLED_FIELD_COLOR_STATE_PRO && fieldFillColor != Common.NORMAL_FIELD_COLOR_STATE_PRO) &&
			(fieldFillColor != Common.DISABLED_FIELD_COLOR_STATE_NONINT && fieldFillColor != Common.NORMAL_FIELD_COLOR_STATE_NONINT) &&
		    (!Common.isFieldAlwaysEnabled(oNode))) {
			BSACommon.enableField(oNode);
		} else {
			BSACommon.enableField(oNode, true);
		}
	}
}  

function enableField(oNode, visualOnly) {
	if (arguments.length < 2) {
	   visualOnly = false;
    }

	if (!visualOnly) {
		oNode.access = "open";
	}

	if (oNode.ui.oneOfChild.className == "button" ) {
		if (!Common.isFieldAlwaysEnabled(oNode)) {
			BSACommon.setButtonColor(oNode);
		}
		else {
			Common.setFillColor(oNode, Common.BUTTON_FILL_COLOR);
			Common.setFontColor(oNode, Common.BUTTON_FONT_COLOR);
		}
	} else if ( oNode.access == "nonInteractive" ){
		Common.setFillColor(oNode, Common.DISABLED_FIELD_COLOR);
	}
	else {
		Common.setFillColor(oNode, Common.NORMAL_FIELD_COLOR);
	}
	Common.processFieldRequiredHighlighting(oNode);
}

