function enableDisableStateUnknown(country, stateUnknown) { 
	if ( Common.hasValue(country) ) {    
		if ( StatesAndCountriesJS.countryIsUSCAMX(country) ) { 
			Common.enableFields(stateUnknown); 
		}
		else {
			BSACommon.disableAndResetFields(stateUnknown); 
		}
	}
}    


function __internalDisableField(oNode, showFieldsAsDisabled, resetValue, saveState) {
	if (oNode != null) {
		if (saveState && oNode.access != "open" && !Common.isFieldAlwaysEnabled(oNode)) {
			//Already not enabled, just save it's state
			if (resetValue && oNode.rawValue != null) {
				oNode.rawValue = null;
			}
			BSACommon.disableField(oNode, true, showFieldsAsDisabled, true);
		} else {		
			if (!Common.isFieldAlwaysEnabled(oNode)) {
				if (resetValue && oNode.rawValue != null) {
					oNode.rawValue = null;
				}
			    BSACommon.disableField(oNode, false, showFieldsAsDisabled, false);
			}
		}
	}
}  

//WARNING: this ALWAYS disables a field, regardless of the existing state and enabled state is NOT saved
function disableField(oNode, visualOnly, showFieldsAsDisabled, saveFieldState) {
	if (arguments.length < 4) {
		saveFieldState = false;
	}

	if (arguments.length < 3) {
		showFieldsAsDisabled = true;
	}

	if (arguments.length < 2) {
		visualOnly = false;
    }

	if (!visualOnly) {
		oNode.access = "nonInteractive";
	}

	if (oNode.ui.oneOfChild.className == "button") {
		if (saveFieldState) {
			if (oNode.access == "readOnly") {
				Common.setFillColor(oNode, Common.BUTTON_DISABLED_FILL_COLOR_STATE_RO);
			} else if (oNode.access == "protected") { 
				Common.setFillColor(oNode, Common.BUTTON_DISABLED_FILL_COLOR_STATE_PRO);
			} else if (oNode.access == "nonInteractive") { 
				Common.setFillColor(oNode, Common.BUTTON_DISABLED_FILL_COLOR_STATE_NONINT);
			} else {
				Common.setFillColor(oNode, Common.BUTTON_DISABLED_FILL_COLOR);
			}
		} else {
			Common.setFillColor(oNode, Common.BUTTON_DISABLED_FILL_COLOR);
		}
		Common.setFontColor(oNode, Common.BUTTON_DISABLED_FONT_COLOR);
	} else {
		if (saveFieldState) {
			if (oNode.access == "readOnly") {
				Common.setFillColor(oNode, (showFieldsAsDisabled) ? Common.DISABLED_FIELD_COLOR_STATE_RO : Common.NORMAL_FIELD_COLOR_STATE_RO);
			} else if (oNode.access == "protected") { 
				Common.setFillColor(oNode, (showFieldsAsDisabled) ? Common.DISABLED_FIELD_COLOR_STATE_PRO : Common.NORMAL_FIELD_COLOR_STATE_PRO);
			} else if (oNode.access == "nonInteractive") { 
				Common.setFillColor(oNode, (showFieldsAsDisabled) ? Common.DISABLED_FIELD_COLOR_STATE_NONINT : Common.NORMAL_FIELD_COLOR_STATE_NONINT);
			} else {
				Common.setFillColor(oNode, (showFieldsAsDisabled) ? Common.DISABLED_FIELD_COLOR : Common.NORMAL_FIELD_COLOR);
			}
		} else {
			Common.setFillColor(oNode, (showFieldsAsDisabled) ? Common.DISABLED_FIELD_COLOR : Common.NORMAL_FIELD_COLOR);
		}
	}
	Common.processFieldRequiredHighlighting(oNode);
}      


//Checks file types and file sizes
function validateAttachmentFiles(deleteMessage, addToErrors) {
	var oDataObjects = event.target.dataObjects;
	var	isValid = true;
	var isBatch = (Common.VALIDATE_ATTACHMENT_FILETYPE == "batch");
	var isXMLBatch = (Common.getFormSubmissionType().indexOf("XBATCH")>0);
	var totalSizeAttachments = 0;
	if (oDataObjects == null || oDataObjects.length < 1) {
		//Nothing to validate
		return true;
	}
	for (var i=0;i<oDataObjects.length;i++) {
		var oDataObject = oDataObjects[i];	
		if (oDataObject != null) {
			var sFileName = oDataObject["path"];
			var sMIMEType = oDataObject["MIMEType"];	
			var regEx = new RegExp(BASE_INVALID_FILENAME, "i");
			if (sFileName != null && sFileName != "" && regEx.test(sFileName)) {
				isValid &= false;
			}

            if(isValid && isXMLBatch && sMIMEType != "text/xml"){
            	isValid &= false;
            }

			regEx = new RegExp(BATCH_INVALID_FILE_MIME_TYPE, "i");
			if (isValid && isBatch && !isXMLBatch && sFileName != null && sFileName != "" && regEx.test(sFileName)) {
				isValid &= false;
			}

			regEx = new RegExp(BASE_INVALID_FILE_MIME_TYPE, "i");
			if (isValid && sMIMEType != null && sMIMEType != "" && regEx.test(sMIMEType )) {
				isValid &= false;
			}

			regEx = new RegExp(BATCH_INVALID_FILE_MIME_TYPE, "i");
			if (isValid && isBatch && !isXMLBatch && sMIMEType != null && sMIMEType != "" && regEx.test(sMIMEType )) {
				isValid &= false;
			}

			if (!isValid) {
				var sMsg = "This form does not allow this type of file to be attached: \"" + sFileName + "\". ";

				if(isXMLBatch) {
				    sMsg += "Only XML files should be attached to this form. ";
				}
				else if (isBatch) {
					sMsg += "Only plain text files should be attached to this form. ";
				}

				if (deleteMessage) {
					sMsg += "\nYou must first use the \"Delete Attachment\" button to delete all of the attachments and " + 
					"then re-attach a valid file using the \"Add Attachment\" button. ";
				}

				if (addToErrors) {
					__setValidationErrorMessage(sMsg);
				} else {
					xfa.host.messageBox(sMsg);
				}
			} else {
				var fileSize = oDataObject["size"];

				if (fileSize > MAX_ATTACHMENTS_SIZE_BYTES || (totalSizeAttachments += fileSize) > MAX_ATTACHMENTS_SIZE_BYTES) {
					var sMsg = "The file \'" + sFileName + "\' is too large to be attached to this form. " + 
						"The maximum size for either an individual file or all files attached to this form may not exceed " +
						MAX_ATTACHMENTS_SIZE_TEXT + ".";

					if (addToErrors) {
						__setValidationErrorMessage(sMsg);
					} else {
						xfa.host.messageBox(sMsg);
					}
					return false;
				}
			}
		}
	}

	return isValid;
}


function processFormValidation() {
	var valid = false;
	try {
		Common.VALIDATING = true;
		valid = xfa.form.execValidate();
		Common.ProcessFields(Common.getFormRoot(), "Common.processFieldRequiredHighlighting");
		//Perform any required file attachment validation
		Common.validateNumberOfAttachments(Common.ALLOWED_NUM_ATTACHMENTS, true);
		BSACommon.validateAttachmentFiles(true, true);

		if (Common.ERRORS.length > 0) {
			var msg = "There are validation errors:\n\n";

			for (var i=0;i<Common.ERRORS.length;i++) {

				// Only display the first 7 messages (Common.ERRORS[0] - Common.ERRORS[6])
				if (i <= 6) {
					msg += (i+1) + ") " + Common.ERRORS[i] + "\n";
				}
			}

			if (Common.ERRORS.length > 7) {
				msg += "\nMessage limit exceeded. Remaining " + 
					(Common.ERRORS.length - 7) + " validation errors not reported.";
			}

			xfa.host.messageBox(msg);
			valid = false;
		}
	} catch(ex) {
		Common.VALIDATING = false;
		Common.ERRORS = new Array();
		valid = false;
	}
	Common.VALIDATING = false;
	Common.ERRORS = new Array();
	return valid;
}          


function processSubmitButtonClick(oNode){
	//Check if we are submitting from within the browser
	if (!event.target.external) {
		xfa.host.messageBox("You must first log in to the BSA E-Filing application in order to submit this form. " +
							"Once logged in, you may then re-open this form and submit.");
		return;
	}

	if (Common.checkViewerVersion()) {
		var valid = true;
		var resetSubmitting = true;

		if (oNode.parent.Submitting.rawValue == "1") {
			xfa.host.messageBox("You may have hit the Submit button more than one time. " + 
				"Please wait until the form finishes submitting and you see the application confirmation page.");
			valid = false;
			resetSubmitting = false;
		}

		//We need to make sure that the button cannot be clicked more than once
		oNode.presence = "invisible";
		oNode.parent.Submitting.rawValue = "1";

		if (valid && !BSACommon.processFormValidation()) {
			xfa.host.messageBox("This form has errors that need to be corrected before submitting.");
			valid = false;
		}

		if (valid && Common.getRequiresPIN() && Common.getActionFields().Signed.rawValue != 1) {
			xfa.host.messageBox("You must sign this form before submitting.");
			valid = false;
		}

		// Determine whether the form data has changed.
		if(valid && Common.initialFormValues != xfa.data.saveXML()){
			xfa.host.messageBox("Form has changed. You must save this form before submitting.");
			valid = false;
		}

		//Submit
		if (valid) {
			try {		
				var additionalParameters = "";
				if (Common.getActionFields() != null) {
					additionalParameters = "&SUBMISSION_VALUE=" 
						+ Common.getActionFields().PINHash.rawValue;
				}			

				var fullURL = Common.getFormSubmissionURL() + "?SUBMISSION_TYPE=" + 
							  Common.getFormSubmissionType() + "&SUBMISSION_NAME=" +
							  encodeURIComponent(Common.getFormSubmissionName()) + 
						      "&NUM_FORMS=" + Common.getNumFormsReported() +
							  additionalParameters;

				if (DEBUG.value == "true") {
					xfa.host.messageBox("Submit URL = " + fullURL );
				}

				oNode.parent.HTTPSubmit.resolveNode("#event.submit").setAttribute(fullURL, "target");
				oNode.parent.Submitted.rawValue = "1";
				oNode.parent.HTTPSubmit.execEvent("click");
			} catch (e) {
			}
		} else {
			// Not a valid submit, show the button again
			oNode.presence = "visible";
			if (resetSubmitting) {
				oNode.parent.Submitting.rawValue = "0";
			}
		}
	}
}

