function processPrePrint(shouldValidate, showECCWarning) {
	var sMessage = "";
	if (shouldValidate && !BSACommon.processFormValidation()) {
		sMessage = "Please note: validation errors have been found on this form.\n\n";
	}

	if (showECCWarning) {
		sMessage += "Printed versions of the BSA E-Filing forms are not for submission " + 
					"and will not be processed by FinCEN.";	
