}            

function processSignButtonClick(oNode, signMsg, unsignMsg) {
	var ActionFields = Common.getActionFields();
	if (ActionFields.Signed.rawValue == null || ActionFields.Signed.rawValue == "" 
		|| ActionFields.Signed.rawValue == 0 || ActionFields.Signed.rawValue == "false" ) {
		try {
			//Applying signature
			Common.SIGNING = true;

			if (ActionFields.Signed.rawValue != 1 && BSACommon.processFormValidation()) {
				var userPIN = "";
				if ((userPIN = PINJS.getPINValue()) != "") {
					var currentDateTime = util.printd("mm/dd/yy hh:MM:ss tt", new Date());
					ActionFields.SignDateTime.formattedValue = currentDateTime;

					var hash = Security.hex_sha1(userPIN);
					ActionFields.PINHash.rawValue = hash;

					//Call the forms applySigntaure() function to handle
					//any custom functionality on the form itself
					try {
						if (COMMON_ApplySigFunc != null && COMMON_ApplySigFunc.value != null) {
							eval(COMMON_ApplySigFunc.value);
						}
					} catch (e) {}

					Common.lockAllFields(Common.getFormRoot());
					ActionFields.Signed.rawValue = 1;
					oNode.caption.value.resolveNode("#text").value = unsignMsg;
				}
			}
		} catch(ex) {
			Common.SIGNING = false;
		}
		Common.SIGNING = false;
	} else {
		//Removing signature
		var ans = xfa.host.messageBox("Are you sure you want to remove your PIN signature from this form?", "Remove PIN Signature?", 2, 2);

		if (ans == 4) {
			ActionFields.Signed.rawValue = 0;
			ActionFields.PINHash.rawValue = null;
			ActionFields.SignDateTime.rawValue = null;

			Common.unlockAllFields(Common.getFormRoot());

			//Call the forms removeSigntaure() function to handle
			//any custom functionality on the form itself
			try {
				if (COMMON_RemoveSigFunc != null && COMMON_RemoveSigFunc.value != null) {
					eval(COMMON_RemoveSigFunc.value);
				}
			} catch (e) {}

			Common.ProcessFields(Common.getFormRoot(), "Common.processFieldRequiredHighlighting");
			Common.savedAfterSigned = false;
			Common.enableDisableSubmitButton(Common.getSubmitButton());
			oNode.caption.value.resolveNode("#text").value = signMsg;
		}
	}
}

function processSignButtonClick(oNode, signMsg, unsignMsg) {
	var ActionFields = Common.getActionFields();
	if (ActionFields.Signed.rawValue == null || ActionFields.Signed.rawValue == "" 
		|| ActionFields.Signed.rawValue == 0 || ActionFields.Signed.rawValue == "false" ) {
		try {
			//Applying signature
			Common.SIGNING = true;

			if (ActionFields.Signed.rawValue != 1 && Common.processFormValidation()) {
				 var ans = SIGNJS.getSIGNValue();
				 if ( ans != "") {
					var currentDateTime = util.printd("mm/dd/yy hh:MM:ss tt", new Date());
					ActionFields.SignDateTime.formattedValue = currentDateTime; 
					//Call the forms applySigntaure() function to handle
					//any custom functionality on the form itself
					try {
						if (COMMON_ApplySigFunc != null && COMMON_ApplySigFunc.value != null) {
							eval(COMMON_ApplySigFunc.value);
						}
					} catch (e) {}

					Common.lockAllFields(Common.getFormRoot());
					ActionFields.Signed.rawValue = 1;
					oNode.caption.value.resolveNode("#text").value = unsignMsg;
				}
			 }
		} catch(ex) {
			Common.SIGNING = false;
		}
		Common.SIGNING = false;
	} else {
		//Removing signature
		var ans = xfa.host.messageBox("Are you sure you want to remove the signature?", "Remove signature?", 2, 2);

		if (ans == 4) {
			ActionFields.Signed.rawValue = 0;
			ActionFields.PINHash.rawValue = null;
			ActionFields.SignDateTime.rawValue = null;

			BSACommon.unlockAllFields(Common.getFormRoot());
			//Call the forms removeSigntaure() function to handle
			//any custom functionality on the form itself
			try {
				if (COMMON_RemoveSigFunc != null && COMMON_RemoveSigFunc.value != null) {
					eval(COMMON_RemoveSigFunc.value);
				}
			} catch (e) {}

			Common.ProcessFields(Common.getFormRoot(), "Common.processFieldRequiredHighlighting");
			Common.savedAfterSigned = false;
			Common.enableDisableSubmitButton(Common.getSubmitButton());
			Common.setFillColor(Header.ValidateButton.Validate, Common.BUTTON_FILL_COLOR);
			Common.setFontColor(Header.ValidateButton.Validate, Common.BUTTON_FONT_COLOR);

			Common.setFillColor(BSAForm.Signature.SigSub.SignatureDate,Common.DISABLED_FIELD_COLOR);
			oNode.caption.value.resolveNode("#text").value = signMsg;
		}
	}
}

function initializeSignButton(oNode,signMsg,unsignMsg) {
	var actionFields = Common.getActionFields();
	if (!Common.isValidReaderVersion()) {
		oNode.presence = "invisible";
	} else {
		Common.setFieldAlwaysEnabled(oNode);
		//Set the button name
		if (actionFields.Signed.rawValue == null || actionFields.Signed.rawValue == "" 
			|| actionFields.Signed.rawValue == 0 || actionFields.Signed.rawValue == "false" ) {
			oNode.caption.value.resolveNode("#text").value =  signMsg;
		} else {
			oNode.caption.value.resolveNode("#text").value = unsignMsg;
		}
	}
}
function processSubmitButtonClick(oNode){
	//Check if we are submitting from within the browser

	if (Common.checkViewerVersion()) {
		var valid = true;
		var resetSubmitting = true;


		if (valid && !Common.processFormValidation()) {
			xfa.host.messageBox("This form has errors that need to be corrected before submitting.");
			valid = false;
		}

		if (valid  && Common.getActionFields().Signed.rawValue != 1) {
			xfa.host.messageBox("You must sign this form before submitting.");
			valid = false;
		}

		// Determine whether the form data has changed.
		if(valid && Common.initialFormValues != xfa.data.saveXML()){
			xfa.host.messageBox("Form has changed. You must save this form before submitting.");
			valid = false;
		}

		//Submit
		if (valid) {
			try {		

			var fullURL = 	Header.SubmitUrl.rawValue			
			app.launchURL(Header.SubmitUrl.rawValue, true);
				if (DEBUG.value == "true") {
					xfa.host.messageBox("Submit URL = " + fullURL );
				}

				//oNode.parent.HTTPSubmit.resolveNode("#event.submit").setAttribute(fullURL, "target");
				oNode.parent.Submitted.rawValue = "1";
			//	oNode.parent.HTTPSubmit.execEvent("click");
			} catch (e) {
			}
		} else {
			// Not a valid submit, show the button again
			oNode.presence = "visible";
			if (resetSubmitting) {
				oNode.parent.Submitting.rawValue = "0";
			}
		}
	}
}

