   initialize: function(dialog)
   {
      dialog.load({"SIGN1":this.SIGNValue});
   },
   commit: function(dialog)
   { 
      this.SIGNValue = "SIGNED";
   },
   validate: function(dialog)
   {
	  return true;
   },
   description:
   {
      name: "Please sign your form",
      //width: 375,
     // align_children: "align_left" ,
      elements:
      [
         {
            type: "view",
            elements:
            [
               {
                  name: "I acknowledge that I am electronically signing the BSA report.",
                  char_height: 3,
                  type: "static_text"
               },

               {
                  alignment: "align_left",
                  type: "ok_cancel",
                  ok_name: "Agree"
               },
            ]
