function getSIGNValue() {
	// Dialog Activation
	SIGN_Dialog.SIGNValue = "";
	if(app.execDialog(SIGN_Dialog) == "ok")	{
    	return SIGN_Dialog.SIGNValue;
	} else {
		return "";
	}
}
